/* 問題集。選択肢の先頭が正解 (出題時に並べ替える)。
   th: 理論  tf: 正誤  ca: 計算 (m は使う方法)。i は重要度。 */
const QUIZ = [];
const th = (c,q,o,e,i=2)=>QUIZ.push({c,k:'th',q,o,e,i});
const tf = (c,q,ans,e,i=2)=>QUIZ.push({c,k:'th',q,tf:ans,e,i});
const ca = (c,m,q,o,e,i=2)=>QUIZ.push({c,k:'ca',m,q,o,e,i});

/* ---------- ベクトル ---------- */
tf('vec',R`零ベクトルにどんなスカラーを掛けても零ベクトルのままである。`,true,R`すべての成分が 0 なので、何を掛けても 0 です。`);
th('vec',R`$\|k\vb{a}\|$ と等しいものはどれですか。`,[R`$|k|\,\|\vb{a}\|$`,R`$k\,\|\vb{a}\|$`,R`$k^2\,\|\vb{a}\|$`,R`$\|\vb{a}\|$`],R`長さは負になりません。$k$ が負のときは向きが逆になり、長さは $|k|$ 倍です。`);
th('vec',R`$\vb{a}-\vb{b}$ を図で表すとどうなりますか。$\vb{a}$ と $\vb{b}$ は原点から描くものとします。`,[R`$\vb{b}$ の先から $\vb{a}$ の先へ向かう矢印`,R`$\vb{a}$ の先から $\vb{b}$ の先へ向かう矢印`,R`$\vb{a}$ の先に $\vb{b}$ をつないだ先へ向かう矢印`,R`$\vb{a}$ と $\vb{b}$ のまん中へ向かう矢印`],R`$\vb{b}+(\vb{a}-\vb{b})=\vb{a}$ です。$\vb{b}$ の先に足すと $\vb{a}$ の先に着く矢印が $\vb{a}-\vb{b}$ です。`);
tf('vec',R`どんな $\vb{a},\vb{b}$ でも $\|\vb{a}+\vb{b}\|=\|\vb{a}\|+\|\vb{b}\|$ が成り立つ。`,false,R`成り立つのは一方が他方の 0 以上のスカラー倍のときだけです。一般には三角不等式 $\|\vb{a}+\vb{b}\|\le\|\vb{a}\|+\|\vb{b}\|$ になります。`);
ca('vec','成分ごとの計算',R`$\vb{a}=\M{2\\-1}$、$\vb{b}=\M{1\\3}$ のとき $2\vb{a}-3\vb{b}$ を求めてください。`,[R`$\M{1\\-11}$`,R`$\M{1\\7}$`,R`$\M{7\\-11}$`,R`$\M{-1\\11}$`],R`$2\vb{a}=\M{4\\-2}$、$3\vb{b}=\M{3\\9}$ です。引くと $\M{4-3\\-2-9}=\M{1\\-11}$。`);
ca('vec','ノルムの公式',R`$\vb{a}=\M{3\\-4\\12}$ の長さを求めてください。`,[R`$13$`,R`$11$`,R`$17$`,R`$19$`],R`$\sqrt{3^2+(-4)^2+12^2}=\sqrt{9+16+144}=\sqrt{169}=13$。`);
ca('vec','正規化',R`$\M{3\\4}$ と同じ向きの単位ベクトルを求めてください。`,[R`$\M{3/5\\4/5}$`,R`$\M{3/7\\4/7}$`,R`$\M{1\\1}$`,R`$\M{3/25\\4/25}$`],R`長さは $\sqrt{9+16}=5$ です。長さで割ると $\M{3/5\\4/5}$。`);

/* ---------- 線形結合・線形独立 ---------- */
th('comb',R`$\vb{v}_1,\dots,\vb{v}_k$ が線形独立であることの定義はどれですか。`,[R`$c_1\vb{v}_1+\cdots+c_k\vb{v}_k=\vb{0}$ となるのは $c_1=\cdots=c_k=0$ のときだけ`,R`$c_1=\cdots=c_k=0$ のとき $c_1\vb{v}_1+\cdots+c_k\vb{v}_k=\vb{0}$ となる`,R`どの 2 本を選んでも平行でない`,R`どのベクトルも零ベクトルでない`],R`2 番目の文は係数が全部 0 なら当たり前に成り立つので、何の条件にもなっていません。「$\vb{0}$ になるのはそのときだけ」が定義です。`,3);
tf('comb',R`零ベクトルを含むベクトルの組は必ず線形従属である。`,true,R`零ベクトルの係数を 1、ほかを 0 にすると、0 でない係数を含む線形結合で $\vb{0}$ が作れます。`,3);
th('comb',R`$\mathbb{R}^3$ のベクトルを 4 本選びました。この組について正しいものはどれですか。`,[R`必ず線形従属である`,R`必ず線形独立である`,R`選び方によって独立にも従属にもなる`,R`必ず $\mathbb{R}^3$ 全体を張る`],R`$\mathbb{R}^n$ で線形独立にできるのは $n$ 本までです。4 本あると必ず余分が出ます。4 本とも同じ直線上にあることもあるので、全体を張るとは限りません。`,3);
th('comb',R`$\M{1\\2}$ と $\M{2\\4}$ が張る空間はどれですか。`,[R`原点を通る直線`,R`平面全体`,R`原点だけ`,R`2 本の直線`],R`$\M{2\\4}=2\M{1\\2}$ なので 2 本は同じ直線上にあります。線形結合で届くのはその直線だけです。`,3);
tf('comb',R`3 本のベクトルのうちどの 2 本も平行でなければ、その 3 本は線形独立である。`,false,R`$\M{1\\0},\M{0\\1},\M{1\\1}$ はどの 2 本も平行ではありませんが、3 本目は前の 2 本の和です。`,3);
th('comb',R`線形従属なベクトルの組について必ず言えることはどれですか。`,[R`取り除いても張る空間が変わらないベクトルが少なくとも 1 本ある`,R`どの 1 本を取り除いても張る空間は変わらない`,R`零ベクトルを含んでいる`,R`張る空間は直線になる`],R`従属な組では、どれか 1 本が残りの線形結合で書けます。その 1 本は取り除いても届く範囲が変わりません。ただしどの 1 本でもよいわけではありません。`);
th('comb',R`$\vb{v}_1,\vb{v}_2$ は線形独立で、$\vb{v}_3=\vb{v}_1+\vb{v}_2$ です。3 本が張る空間の次元はいくつですか。`,[R`$2$`,R`$3$`,R`$1$`,R`$0$`],R`$\vb{v}_3$ は前の 2 本で作れるので、届く範囲を広げません。次元は 2 のままです。`);
th('comb',R`線形独立な組からベクトルを何本か取り除きました。残った組はどうなりますか。`,[R`必ず線形独立`,R`必ず線形従属`,R`どちらにもなりうる`,R`零ベクトルだけが残る`],R`残った組で $\vb{0}$ を作る 0 でない係数があれば、取り除いたベクトルの係数を 0 として元の組でも $\vb{0}$ が作れてしまいます。`);
ca('comb','行列式で判定',R`$\M{1\\2}$ と $\M{3\\k}$ が線形従属になる $k$ を求めてください。`,[R`$6$`,R`$\dfrac32$`,R`$-6$`,R`$\dfrac23$`],R`2 本を並べた行列の行列式が 0 のとき従属です。$1\cdot k-3\cdot2=0$ から $k=6$。このとき $\M{3\\6}=3\M{1\\2}$ です。`,3);
ca('comb','連立方程式で係数を求める',R`$\M{5\\4}=s\M{1\\2}+t\M{3\\0}$ となる $(s,t)$ を求めてください。`,[R`$(2,\,1)$`,R`$(1,\,2)$`,R`$(2,\,-1)$`,R`$(4,\,\tfrac13)$`],R`下の成分から $2s=4$ で $s=2$。上の成分に入れて $2+3t=5$ から $t=1$。`);
ca('comb','掃き出し法で判定',R`$\M{1\\1\\0},\M{0\\1\\1},\M{1\\2\\1}$ のうち線形独立に選べる最大の本数はいくつですか。`,[R`$2$`,R`$3$`,R`$1$`,R`$0$`],R`3 本を列に並べて掃き出すと 0 でない行が 2 つ残ります。実際に 3 本目は 1 本目と 2 本目の和です。`,3);

/* ---------- 内積 ---------- */
th('dot',R`$\vb{a}\cdot\vb{b}<0$ のとき、2 つのなす角について言えることはどれですか。`,[R`90°より大きい`,R`90°より小さい`,R`ちょうど 90°`,R`ちょうど 0°`],R`$\vb{a}\cdot\vb{b}=\|\vb{a}\|\|\vb{b}\|\cos\theta$ で、長さは正です。内積が負なら $\cos\theta<0$ なので鈍角です。`);
th('dot',R`$\vb{a}\cdot\vb{a}$ と等しいものはどれですか。`,[R`$\|\vb{a}\|^2$`,R`$\|\vb{a}\|$`,R`$2\|\vb{a}\|$`,R`$0$`],R`自分自身とのなす角は 0 なので $\cos\theta=1$ です。成分で見ても $a_1^2+\cdots+a_n^2$ で、長さの 2 乗です。`,3);
th('dot',R`コーシー・シュワルツの不等式 $|\vb{a}\cdot\vb{b}|\le\|\vb{a}\|\|\vb{b}\|$ で等号が成り立つのはいつですか。`,[R`一方が他方のスカラー倍のとき`,R`2 つが直交するとき`,R`2 つの長さが等しいとき`,R`どちらも単位ベクトルのとき`],R`等号は 2 本が同じ直線上にあるときです。どちらかが零ベクトルの場合も、両辺が 0 で等号が成り立ちます。`);
tf('dot',R`2 つのベクトルの内積はベクトルである。`,false,R`内積の結果は 1 つの数 (スカラー) です。結果がベクトルになるのは外積です。`,3);
th('dot',R`$\mathbb{R}^3$ の外積 $\vb{a}\times\vb{b}$ について正しいものはどれですか。`,[R`$\vb{a}$ と $\vb{b}$ の両方に直交する`,R`$\vb{a}$ と $\vb{b}$ が作る平面の中にある`,R`$\vb{b}\times\vb{a}$ と等しい`,R`結果は数である`],R`外積は 2 つのベクトルの両方に垂直なベクトルです。順序を入れ替えると符号が変わります。`);
th('dot',R`$\vb{b}\ne\vb{0}$ とします。$\vb{a}$ から $\vb{b}$ への正射影を引いた残り $\vb{a}-\mathrm{proj}_{\vb{b}}\vb{a}$ について、どんな $\vb{a}$ でも成り立つものはどれですか。`,[R`$\vb{b}$ と直交する`,R`$\vb{b}$ と平行である`,R`$\vb{a}$ と直交する`,R`必ず零ベクトルになる`],R`影の成分を取り除くと、$\vb{b}$ に垂直な成分だけが残ります。グラム・シュミットの直交化はこの性質を使います。`,3);
tf('dot',R`零ベクトルは、内積が 0 という意味でどのベクトルとも直交する。`,true,R`$\vb{0}\cdot\vb{a}=0$ がどんな $\vb{a}$ でも成り立ちます。`);
ca('dot','成分で計算',R`$\M{1\\2\\3}\cdot\M{4\\-5\\6}$ を求めてください。`,[R`$12$`,R`$32$`,R`$-12$`,R`$8$`],R`$1\cdot4+2\cdot(-5)+3\cdot6=4-10+18=12$。`);
ca('dot','なす角の公式',R`$\vb{a}=\M{2\\1}$ と $\vb{b}=\M{1\\3}$ のなす角を求めてください。`,[R`45°`,R`30°`,R`60°`,R`90°`],R`$\vb{a}\cdot\vb{b}=5$、$\|\vb{a}\|=\sqrt5$、$\|\vb{b}\|=\sqrt{10}$ です。$\cos\theta=\dfrac{5}{\sqrt{50}}=\dfrac{1}{\sqrt2}$ なので 45°。`);
ca('dot','正射影の公式',R`$\vb{a}=\M{2\\3}$ の $\vb{b}=\M{1\\1}$ への正射影を求めてください。`,[R`$\M{5/2\\5/2}$`,R`$\M{5\\5}$`,R`$\M{1\\1}$`,R`$\M{2\\2}$`],R`係数は $\dfrac{\vb{a}\cdot\vb{b}}{\vb{b}\cdot\vb{b}}=\dfrac{5}{2}$。これを $\vb{b}$ に掛けて $\M{5/2\\5/2}$。`);
ca('dot','直交条件',R`$\M{2\\k\\1}$ と $\M{1\\-1\\4}$ が直交する $k$ を求めてください。`,[R`$6$`,R`$-6$`,R`$2$`,R`$-2$`],R`内積が 0 になればよいので $2-k+4=0$。$k=6$。`);
ca('dot','外積の成分公式',R`$\M{1\\0\\2}\times\M{0\\1\\3}$ を求めてください。`,[R`$\M{-2\\-3\\1}$`,R`$\M{2\\3\\-1}$`,R`$\M{-2\\3\\1}$`,R`$\M{2\\-3\\1}$`],R`$\M{a_2b_3-a_3b_2\\a_3b_1-a_1b_3\\a_1b_2-a_2b_1}=\M{0\cdot3-2\cdot1\\2\cdot0-1\cdot3\\1\cdot1-0\cdot0}=\M{-2\\-3\\1}$。元の 2 本との内積がどちらも 0 になることで確かめられます。`);

/* ---------- 行列と線形変換 ---------- */
th('map',R`2 次の行列の 2 列目は何を表していますか。`,[R`$\vb{e}_2=\M{0\\1}$ の行き先`,R`$\vb{e}_1=\M{1\\0}$ の行き先`,R`$y$ 軸方向の倍率`,R`2 番目の式の係数`],R`$A\vb{e}_2$ を計算すると 2 列目がそのまま出てきます。列は基底ベクトルの行き先です。`,3);
th('map',R`次のうち線形写像でないものはどれですか。`,[R`$f(x,y)=(x+1,\;y)$`,R`$f(x,y)=(2x,\;y)$`,R`$f(x,y)=(y,\;x)$`,R`$f(x,y)=(x+y,\;0)$`],R`$f(0,0)=(1,0)$ で原点が動いています。線形写像は必ず $\vb{0}$ を $\vb{0}$ に移します。`,3);
th('map',R`$3\times2$ 行列が表す線形写像はどれですか。`,[R`$\mathbb{R}^2$ から $\mathbb{R}^3$ へ`,R`$\mathbb{R}^3$ から $\mathbb{R}^2$ へ`,R`$\mathbb{R}^3$ から $\mathbb{R}^3$ へ`,R`$\mathbb{R}^2$ から $\mathbb{R}^2$ へ`],R`列の数 2 が入力の次元、行の数 3 が出力の次元です。`,3);
tf('map',R`線形写像は必ず原点を原点へ移す。`,true,R`$f(\vb{0})=f(0\cdot\vb{v})=0\cdot f(\vb{v})=\vb{0}$ です。`,3);
th('map',R`$A\vb{x}$ について正しいものはどれですか。`,[R`$A$ の列の線形結合で、係数は $\vb{x}$ の成分`,R`$A$ の行の線形結合で、係数は $\vb{x}$ の成分`,R`$A$ の対角成分と $\vb{x}$ の内積`,R`$A$ の各成分に $\vb{x}$ の長さを掛けたもの`],R`$A\vb{x}=x_1\vb{a}_1+\cdots+x_n\vb{a}_n$ です。この見方から「像 $=$ 列空間」が出てきます。`,3);
th('map',R`平面を反時計回りに 90° 回す行列はどれですか。`,[R`$\M{0&-1\\1&0}$`,R`$\M{0&1\\-1&0}$`,R`$\M{-1&0\\0&-1}$`,R`$\M{0&1\\1&0}$`],R`$\vb{e}_1$ は $\M{0\\1}$ へ、$\vb{e}_2$ は $\M{-1\\0}$ へ移ります。この 2 つを列に並べます。`);
th('map',R`線形変換で保たれるとは限らないものはどれですか。`,[R`ベクトルの長さ`,R`原点が原点に移ること`,R`和が和に移ること`,R`スカラー倍の関係`],R`拡大やせん断では長さが変わります。長さを保つのは直交行列が表す変換だけです。`);
ca('map','列の線形結合として計算',R`$\M{2&1\\0&3}\M{1\\2}$ を求めてください。`,[R`$\M{4\\6}$`,R`$\M{2\\6}$`,R`$\M{4\\3}$`,R`$\M{3\\6}$`],R`$1\cdot\M{2\\0}+2\cdot\M{1\\3}=\M{4\\6}$。`);
ca('map','基底の行き先から行列を作る',R`線形変換 $f$ が $\vb{e}_1$ を $\M{2\\1}$ へ、$\vb{e}_2$ を $\M{-1\\3}$ へ移します。$f$ を表す行列はどれですか。`,[R`$\M{2&-1\\1&3}$`,R`$\M{2&1\\-1&3}$`,R`$\M{-1&2\\3&1}$`,R`$\M{1&3\\2&-1}$`],R`行き先をそのまま列に並べます。横に並べてしまうと転置になるので注意します。`,3);
ca('map','線形性を使う',R`線形写像 $f$ について $f(\vb{v})=\M{1\\2}$、$f(\vb{w})=\M{0\\3}$ です。$f(2\vb{v}-\vb{w})$ を求めてください。`,[R`$\M{2\\1}$`,R`$\M{2\\7}$`,R`$\M{1\\-1}$`,R`$\M{2\\4}$`],R`線形性から $f(2\vb{v}-\vb{w})=2f(\vb{v})-f(\vb{w})=\M{2\\4}-\M{0\\3}=\M{2\\1}$。$\vb{v}$ や $\vb{w}$ そのものがわからなくても求まります。`);

/* ---------- 積と逆行列 ---------- */
th('prod',R`積 $AB$ が表す変換はどれですか。`,[R`$B$ を行ってから $A$ を行う`,R`$A$ を行ってから $B$ を行う`,R`$A$ と $B$ を同時に行う`,R`$A$ と $B$ の平均を取る`],R`$AB\vb{x}=A(B\vb{x})$ です。ベクトルに近い右側の行列が先に働きます。`,3);
th('prod',R`$A$ と $B$ が正則のとき $(AB)^{-1}$ と等しいものはどれですか。`,[R`$B^{-1}A^{-1}$`,R`$A^{-1}B^{-1}$`,R`$(BA)^{-1}$`,R`$A^{-1}+B^{-1}$`],R`$AB\cdot B^{-1}A^{-1}=A\,I\,A^{-1}=I$ です。あとで行った操作を先に戻します。`,3);
tf('prod',R`$AB=O$ ならば $A=O$ または $B=O$ である。`,false,R`$\M{1&0\\0&0}\M{0&0\\0&1}=O$ のように、どちらも零行列でなくても積が零行列になります。`);
th('prod',R`$2\times3$ 行列と $3\times4$ 行列の積の型はどれですか。`,[R`$2\times4$`,R`$3\times3$`,R`$4\times2$`,R`積は作れない`],R`内側の 3 と 3 がそろっているので積が作れます。結果は外側の $2\times4$ です。`);
th('prod',R`直交行列を掛けても変わらないものはどれですか。`,[R`ベクトルの長さ`,R`ベクトルの向き`,R`ベクトルの各成分`,R`ベクトルの第 1 成分`],R`$\|Q\vb{x}\|^2=\vb{x}^{\mathsf T}Q^{\mathsf T}Q\vb{x}=\vb{x}^{\mathsf T}\vb{x}$ です。回転や鏡映は長さを変えません。`);
th('prod',R`$(AB)^{\mathsf T}$ と等しいものはどれですか。`,[R`$B^{\mathsf T}A^{\mathsf T}$`,R`$A^{\mathsf T}B^{\mathsf T}$`,R`$AB$`,R`$BA$`],R`逆行列と同じく、転置でも積の順序が逆になります。`);
tf('prod',R`$A$ と $B$ がどちらも $n$ 次の正則行列なら、$AB$ も正則である。`,true,R`$B^{-1}A^{-1}$ が逆行列になります。行列式で見ても $\det(AB)=\det A\det B\ne0$ です。`);
th('prod',R`どんな行列 $A$ についても対称行列になるものはどれですか。`,[R`$A^{\mathsf T}A$`,R`$A-A^{\mathsf T}$`,R`$A^2$`,R`$A+I$`],R`$(A^{\mathsf T}A)^{\mathsf T}=A^{\mathsf T}(A^{\mathsf T})^{\mathsf T}=A^{\mathsf T}A$ です。最小二乗法や特異値分解に出てくる形です。`);
ca('prod','積の定義 (行と列の内積)',R`$\M{1&2\\3&4}\M{0&1\\1&0}$ を求めてください。`,[R`$\M{2&1\\4&3}$`,R`$\M{3&4\\1&2}$`,R`$\M{0&2\\3&0}$`,R`$\M{2&1\\3&4}$`],R`$(1,1)$ 成分は $1\cdot0+2\cdot1=2$、$(1,2)$ 成分は $1\cdot1+2\cdot0=1$。同じように $(2,1)=4$、$(2,2)=3$。右から掛けた行列は列を入れ替える働きをしています。`);
ca('prod','2 次の逆行列の公式',R`$\M{2&1\\5&3}$ の逆行列を求めてください。`,[R`$\M{3&-1\\-5&2}$`,R`$\M{3&1\\5&2}$`,R`$\M{-3&1\\5&-2}$`,R`$\M{2&-1\\-5&3}$`],R`$ad-bc=6-5=1$ です。対角を入れ替え、残りの符号を変えて $\dfrac11\M{3&-1\\-5&2}$。`,3);
ca('sys','掃き出し法 (A | I)',R`$(A\mid I)$ を行基本変形して $(I\mid A^{-1})$ にする方法で、$A=\M{1&2\\1&3}$ の逆行列を求めてください。`,[R`$\M{3&-2\\-1&1}$`,R`$\M{3&2\\1&1}$`,R`$\M{1&-2\\-1&3}$`,R`$\M{-3&2\\1&-1}$`],R`$\left(\begin{array}{cc|cc}1&2&1&0\\1&3&0&1\end{array}\right)$ で 2 行目から 1 行目を引くと $\left(\begin{array}{cc|cc}1&2&1&0\\0&1&-1&1\end{array}\right)$。1 行目から 2 行目の 2 倍を引くと $\left(\begin{array}{cc|cc}1&0&3&-2\\0&1&-1&1\end{array}\right)$。`,3);
ca('prod','対角行列の逆',R`$\M{1&0&0\\0&2&0\\0&0&4}$ の逆行列を求めてください。`,[R`$\M{1&0&0\\0&1/2&0\\0&0&1/4}$`,R`$\M{-1&0&0\\0&-2&0\\0&0&-4}$`,R`$\M{4&0&0\\0&2&0\\0&0&1}$`,R`$\M{1&0&0\\0&1/4&0\\0&0&1/2}$`],R`対角行列は軸ごとの伸び縮みです。元に戻すには各軸を逆数倍します。`);
ca('prod','べき乗の規則性を見つける',R`$\M{1&1\\0&1}^3$ を求めてください。`,[R`$\M{1&3\\0&1}$`,R`$\M{1&1\\0&1}$`,R`$\M{3&3\\0&3}$`,R`$\M{1&8\\0&1}$`],R`2 乗すると $\M{1&2\\0&1}$、もう一度掛けると $\M{1&3\\0&1}$ です。せん断を $n$ 回くり返すと、ずれが $n$ 倍になります。`);

/* ---------- 行列式 ---------- */
th('det',R`$\det A=0$ のとき、$A$ が表す平面の変換で起きていることはどれですか。`,[R`平面が直線か点につぶれる`,R`平面が裏返る`,R`面積が変わらない`,R`何も動かない`],R`面積の倍率が 0 なので、広がりのある図形が広がりのないものに移ります。元に戻せないので逆行列がありません。`,3);
th('det',R`$\det A<0$ は何を表していますか。`,[R`向きが裏返っている`,R`面積が縮んでいる`,R`逆行列がない`,R`回転を含んでいる`],R`符号は向きを表します。$\vb{e}_1$ から $\vb{e}_2$ へ反時計回りだった位置関係が、行き先では時計回りになっています。`);
th('det',R`行列の 2 つの行を入れ替えると行列式はどうなりますか。`,[R`符号が変わる`,R`変わらない`,R`0 になる`,R`2 倍になる`],R`これを交代性と呼びます。同じ行が 2 つある行列は入れ替えても同じなので、行列式は 0 しかありえません。`,3);
th('det',R`$A$ が 3 次の正方行列のとき $\det(2A)$ はどれですか。`,[R`$8\det A$`,R`$2\det A$`,R`$6\det A$`,R`$\det A$`],R`3 つの行がそれぞれ 2 倍されるので $2^3=8$ 倍です。体積で考えると、辺を全部 2 倍にした箱の体積は 8 倍です。`,3);
tf('det',R`どんな正方行列でも $\det(A+B)=\det A+\det B$ が成り立つ。`,false,R`$A=B=I$ (2 次) なら左辺は $\det(2I)=4$、右辺は $2$ です。成り立つのは積についての $\det(AB)=\det A\det B$ です。`,3);
th('det',R`$A$ が正則のとき $\det(A^{-1})$ と等しいものはどれですか。`,[R`$\dfrac{1}{\det A}$`,R`$-\det A$`,R`$\det A$`,R`$1$`],R`$\det A\cdot\det A^{-1}=\det(AA^{-1})=\det I=1$ です。`);
th('det',R`ある行に別の行の 3 倍を足しました。行列式はどうなりますか。`,[R`変わらない`,R`3 倍になる`,R`符号が変わる`,R`3 だけ増える`],R`この操作は行列式を変えません。だから掃き出しながら行列式を計算できます。`,3);
th('det',R`三角行列の行列式はどれですか。`,[R`対角成分の積`,R`対角成分の和`,R`すべての成分の積`,R`必ず 0`],R`余因子展開を 1 列目からくり返すと、対角成分だけが掛け合わされて残ります。`);
tf('det',R`列ベクトルが線形従属な正方行列の行列式は 0 である。`,true,R`列が従属なら像の次元が下がり、図形がつぶれます。面積や体積の倍率は 0 です。`,3);
ca('det','2 次の公式',R`$\D{3&2\\1&4}$ を求めてください。`,[R`$10$`,R`$14$`,R`$5$`,R`$-10$`],R`$ad-bc=3\cdot4-2\cdot1=10$。`);
ca('det','サラスの方法',R`サラスの方法で $\D{1&2&3\\0&1&4\\5&6&0}$ を求めてください。`,[R`$1$`,R`$-1$`,R`$79$`,R`$25$`],R`右下がりの積の和は $1\cdot1\cdot0+2\cdot4\cdot5+3\cdot0\cdot6=40$。左下がりの積の和は $3\cdot1\cdot5+2\cdot0\cdot0+1\cdot4\cdot6=39$。差は $40-39=1$。`);
ca('det','余因子展開',R`0 の多い列で余因子展開して $\D{2&0&1\\3&0&2\\1&4&5}$ を求めてください。`,[R`$-4$`,R`$4$`,R`$-16$`,R`$12$`],R`2 列目は 4 以外が 0 です。4 は 3 行 2 列にあるので符号は $(-1)^{3+2}=-1$。残りの小行列式は $\D{2&1\\3&2}=1$。よって $4\cdot(-1)\cdot1=-4$。`,3);
ca('det','行基本変形で三角行列にする',R`行基本変形で三角行列に直して $\D{1&2&1\\2&5&3\\1&3&4}$ を求めてください。`,[R`$2$`,R`$-2$`,R`$20$`,R`$0$`],R`2 行目から 1 行目の 2 倍、3 行目から 1 行目を引くと $\D{1&2&1\\0&1&1\\0&1&3}$。3 行目から 2 行目を引くと $\D{1&2&1\\0&1&1\\0&0&2}$。対角成分の積は $2$。足し引きだけなので符号は変わりません。`,3);
ca('det','積の性質を使う',R`$A,B$ は 3 次の正方行列で $\det A=3$、$\det B=-2$ です。$\det(2AB^{-1})$ を求めてください。`,[R`$-12$`,R`$-3$`,R`$-48$`,R`$12$`],R`$\det(2A)=2^3\cdot3=24$、$\det(B^{-1})=-\dfrac12$。掛けて $-12$。`);
ca('det','三角行列の性質',R`$\D{2&7&1\\0&3&9\\0&0&-1}$ を求めてください。`,[R`$-6$`,R`$6$`,R`$4$`,R`$-378$`],R`上三角行列なので対角成分の積 $2\cdot3\cdot(-1)=-6$。対角より上の数は関係しません。`);
ca('det','面積への応用',R`$\M{3\\1}$ と $\M{1\\2}$ を 2 辺とする平行四辺形の面積を求めてください。`,[R`$5$`,R`$7$`,R`$\dfrac52$`,R`$6$`],R`2 本を列に並べた行列の行列式の絶対値です。$|3\cdot2-1\cdot1|=5$。`);

/* ---------- 連立一次方程式 ---------- */
th('sys',R`$A\vb{x}=\vb{b}$ に解がないのはどの場合ですか。`,[R`$\mathrm{rank}\,A<\mathrm{rank}\,(A\mid\vb{b})$`,R`$\mathrm{rank}\,A=\mathrm{rank}\,(A\mid\vb{b})$`,R`$\mathrm{rank}\,A$ が未知数の数より小さい`,R`式の数が未知数の数より多い`],R`掃き出したとき $0=1$ のような行が出るのがこの場合です。式が多くても解があることはあります。`,3);
th('sys',R`未知数が 5 個で $\mathrm{rank}\,A=\mathrm{rank}\,(A\mid\vb{b})=3$ です。自由変数はいくつありますか。`,[R`$2$`,R`$3$`,R`$5$`,R`$0$`],R`自由変数の数は「未知数の数 $-$ ランク」で $5-3=2$。解は 2 つの任意定数を含みます。`,3);
th('sys',R`行基本変形に含まれないものはどれですか。`,[R`2 つの列を入れ替える`,R`2 つの行を入れ替える`,R`ある行を 0 でない数で何倍かする`,R`ある行に別の行の何倍かを足す`],R`列を入れ替えると未知数の順番が変わってしまいます。行の操作は式の操作なので解を変えません。`,3);
tf('sys',R`同次連立一次方程式 $A\vb{x}=\vb{0}$ は必ず解をもつ。`,true,R`$\vb{x}=\vb{0}$ がいつでも解です。これを自明な解と呼びます。`,3);
th('sys',R`未知数が 3 個、式が 2 本の同次連立一次方程式について正しいものはどれですか。`,[R`$\vb{0}$ 以外の解を必ずもつ`,R`解は $\vb{0}$ だけである`,R`解をもたないことがある`,R`解はちょうど 2 個ある`],R`ランクは最大でも 2 なので、自由変数が 1 つ以上残ります。式より未知数が多い同次方程式は必ず非自明な解をもちます。`);
th('det',R`クラメルの公式が使えるのはどの場合ですか。`,[R`係数行列が正則のとき`,R`係数行列が対称のとき`,R`右辺が $\vb{0}$ のとき`,R`どんな連立一次方程式にも使える`],R`公式の分母が $\det A$ です。0 のときは割れません。`);
th('sys',R`$A$ が $n$ 次の正則行列のとき、$A\vb{x}=\vb{b}$ の解について正しいものはどれですか。`,[R`どんな $\vb{b}$ でもただ 1 つある`,R`$\vb{b}$ によっては解がない`,R`無数にある`,R`$\vb{b}=\vb{0}$ のときだけある`],R`両辺に左から $A^{-1}$ を掛けると $\vb{x}=A^{-1}\vb{b}$ と決まります。`,3);
tf('sys',R`式の数と未知数の数が等しい連立一次方程式は、必ず解をちょうど 1 つもつ。`,false,R`$x+y=1$、$2x+2y=2$ は解が無数、$x+y=1$、$x+y=2$ は解なしです。解が 1 つなのは係数行列が正則のときです。`);
th('sys',R`行基本変形をすると値が変わることがあるものはどれですか。連立方程式では拡大係数行列に対して変形を行うものとします。`,[R`行列式`,R`ランク`,R`連立一次方程式の解`,R`核`],R`行を入れ替えると行列式の符号が変わり、行を $k$ 倍すると行列式も $k$ 倍になります。ランクと解と核は変わりません。`);
ca('sys','掃き出し法',R`掃き出し法で $\begin{cases}x+2y=5\\3x-y=1\end{cases}$ を解いてください。`,[R`$(x,y)=(1,2)$`,R`$(x,y)=(2,1)$`,R`$(x,y)=(3,1)$`,R`$(x,y)=(-1,3)$`],R`$\left(\begin{array}{cc|c}1&2&5\\3&-1&1\end{array}\right)$ の 2 行目から 1 行目の 3 倍を引くと $\left(\begin{array}{cc|c}1&2&5\\0&-7&-14\end{array}\right)$。$y=2$、1 行目に戻して $x=1$。`,3);
ca('det','クラメルの公式',R`クラメルの公式で $\begin{cases}2x+y=5\\x+3y=5\end{cases}$ の $x$ を求めてください。`,[R`$2$`,R`$1$`,R`$\dfrac52$`,R`$4$`],R`$\det A=\D{2&1\\1&3}=5$。1 列目を右辺に置き換えて $\D{5&1\\5&3}=10$。$x=\dfrac{10}{5}=2$。`);
ca('sys','逆行列を掛ける',R`$\M{2&1\\5&3}\vb{x}=\M{1\\2}$ を、逆行列を使って解いてください。`,[R`$\M{1\\-1}$`,R`$\M{-1\\1}$`,R`$\M{5\\9}$`,R`$\M{1\\1}$`],R`$A^{-1}=\M{3&-1\\-5&2}$ です。$\vb{x}=A^{-1}\M{1\\2}=\M{3-2\\-5+4}=\M{1\\-1}$。`);
ca('sys','ランクで判定',R`$\begin{cases}x+y=2\\2x+2y=5\end{cases}$ の解について正しいものはどれですか。`,[R`解はない`,R`解はただ 1 つ`,R`解は無数にある`,R`解は 2 つ`],R`2 行目から 1 行目の 2 倍を引くと $0=1$ になります。$\mathrm{rank}\,A=1$、$\mathrm{rank}\,(A\mid\vb{b})=2$ で等しくありません。図では平行な 2 直線です。`,3);
ca('sys','自由変数をおいて一般解を書く',R`$\begin{cases}x+y+z=3\\y+2z=1\end{cases}$ の一般解はどれですか。$t$ は任意の実数です。`,[R`$\M{2\\1\\0}+t\M{1\\-2\\1}$`,R`$\M{2\\1\\0}+t\M{1\\2\\1}$`,R`$\M{3\\1\\0}+t\M{1\\-2\\1}$`,R`$\M{2\\1\\0}$ だけ`],R`ピボットのない $z$ を $t$ とおきます。$y=1-2t$、$x=3-y-z=2+t$。まとめると $\M{2\\1\\0}+t\M{1\\-2\\1}$。前半が特殊解、後半が同次方程式の解です。`,3);
ca('sys','後退代入',R`$\begin{cases}x+y+z=6\\2y+z=7\\z=3\end{cases}$ を下の式から順に解いてください。`,[R`$(1,2,3)$`,R`$(2,1,3)$`,R`$(3,2,1)$`,R`$(1,3,2)$`],R`$z=3$。2 番目の式から $2y=4$ で $y=2$。1 番目の式から $x=6-2-3=1$。階段の形になっていれば下から代入するだけで解けます。`);

/* ---------- ランク・核・像 ---------- */
th('rank',R`$3\times5$ 行列 $A$ のランクが 2 です。核の次元はいくつですか。`,[R`$3$`,R`$1$`,R`$2$`,R`$5$`],R`次元定理で、入力の次元は列の数 5 です。$5-2=3$。行の数 3 から引くのは誤りです。`,3);
th('rank',R`行列 $A$ の像と同じものはどれですか。`,[R`列空間`,R`行空間`,R`核`,R`固有空間`],R`$A\vb{x}$ は列の線形結合です。$\vb{x}$ を自由に動かすと、列が張る空間の全体になります。`,3);
th('rank',R`線形写像の核が $\{\vb{0}\}$ だけであることと同じ条件はどれですか。`,[R`単射である`,R`全射である`,R`像が $\{\vb{0}\}$ である`,R`行列式が 0 である`],R`$A\vb{x}=A\vb{y}$ なら $A(\vb{x}-\vb{y})=\vb{0}$ です。核が $\vb{0}$ だけなら $\vb{x}=\vb{y}$ となり、違う点は違う点に移ります。`);
tf('rank',R`どんな行列でも $\mathrm{rank}\,A=\mathrm{rank}\,A^{\mathsf T}$ が成り立つ。`,true,R`線形独立な列の最大本数と、線形独立な行の最大本数は必ず一致します。`);
th('rank',R`$n$ 次正方行列 $A$ が正則であることと同じ条件でないものはどれですか。`,[R`トレースが 0 でない`,R`$\det A\ne0$`,R`ランクが $n$`,R`核が $\{\vb{0}\}$ だけ`],R`$\M{1&0\\0&-1}$ はトレースが 0 ですが正則です。残りの 3 つは正則性と同じ条件です。`,3);
th('rank',R`$4\times3$ 行列のランクは最大でいくつですか。`,[R`$3$`,R`$4$`,R`$7$`,R`$12$`],R`ランクは行の数も列の数も超えません。小さい方の 3 が上限です。`);
tf('rank',R`$m\times n$ 行列の核は $\mathbb{R}^n$ の部分空間である。`,true,R`核は入力側の空間にあります。$\vb{0}$ を含み、和とスカラー倍で閉じています。`);
th('rank',R`3 次正方行列 $A$ のランクが 2 のとき、$A\vb{x}=\vb{0}$ の解の全体はどんな図形ですか。`,[R`原点を通る直線`,R`原点を通る平面`,R`原点だけ`,R`空間全体`],R`核の次元は $3-2=1$ です。1 次元の部分空間は原点を通る直線です。`,3);
th('rank',R`$2\times3$ 行列が表す線形写像について正しいものはどれですか。`,[R`単射にはなれない`,R`全射にはなれない`,R`必ず全射である`,R`必ず単射である`],R`ランクは最大 2 なので、核の次元は $3-2=1$ 以上です。3 次元を 2 次元に移すと必ずどこかがつぶれます。`);
ca('rank','掃き出し法でランクを求める',R`$\M{1&2&3\\2&4&6\\1&0&1}$ のランクを求めてください。`,[R`$2$`,R`$3$`,R`$1$`,R`$0$`],R`2 行目は 1 行目の 2 倍なので、引くと 0 の行になります。3 行目から 1 行目を引くと $(0,-2,-2)$ で、これは残ります。0 でない行は 2 つです。`,3);
ca('rank','核を求める (同次方程式を解く)',R`$\M{1&2\\2&4}$ の核はどれですか。$t$ は任意の実数です。`,[R`$t\M{2\\-1}$`,R`$t\M{1\\2}$`,R`$t\M{1\\-2}$`,R`$\vb{0}$ だけ`],R`2 本の式はどちらも $x+2y=0$ と同じです。$y=-t$ とおくと $x=2t$ で、$t\M{2\\-1}$。`,3);
ca('rank','次元定理',R`$5\times7$ 行列の核の次元が 4 です。ランクを求めてください。`,[R`$3$`,R`$1$`,R`$4$`,R`$2$`],R`入力の次元は列の数 7 です。$7-4=3$。`);
ca('rank','像を求める (列空間)',R`$\M{1&2\\2&4}$ の像はどれですか。$t$ は任意の実数です。`,[R`$t\M{1\\2}$`,R`$t\M{2\\-1}$`,R`$\mathbb{R}^2$ 全体`,R`$\vb{0}$ だけ`],R`像は列が張る空間です。2 列目は 1 列目の 2 倍なので、張る空間は $\M{1\\2}$ の方向の直線です。核 $t\M{2\\-1}$ と混同しないようにします。`);

/* ---------- ベクトル空間と基底 ---------- */
th('space',R`$\mathbb{R}^2$ の部分空間でないものはどれですか。`,[R`直線 $y=x+1$`,R`直線 $y=2x$`,R`原点だけの集合`,R`$\mathbb{R}^2$ 全体`],R`$y=x+1$ は原点を通りません。$\vb{0}$ を含まない集合は部分空間になれません。`,3);
th('space',R`ベクトルの組が基底であるための条件はどれですか。`,[R`線形独立で、空間全体を張る`,R`線形独立である`,R`空間全体を張る`,R`互いに直交し、長さが 1 である`],R`独立だけでは足りず、張るだけでは余分があるかもしれません。両方が必要です。直交や長さ 1 は基底の条件ではありません。`,3);
th('space',R`ベクトル空間の次元とは何ですか。`,[R`基底に含まれるベクトルの本数`,R`ベクトルの成分の個数`,R`空間に含まれるベクトルの個数`,R`線形従属なベクトルの最大本数`],R`基底の取り方はいろいろありますが、本数はいつも同じです。成分が 3 個のベクトルでできた平面は 2 次元です。`,3);
tf('space',R`$\mathbb{R}^3$ の基底は、どれを選んでも 3 本のベクトルからなる。`,true,R`2 本では空間全体を張れず、4 本では線形従属になります。`);
th('space',R`2 次以下の実係数多項式の全体は、何次元のベクトル空間ですか。`,[R`$3$`,R`$2$`,R`$1$`,R`無限次元`],R`$1,\ x,\ x^2$ が基底になります。$a+bx+cx^2$ は 3 つの係数で決まります。`);
tf('space',R`2 つの部分空間の和集合は必ず部分空間になる。`,false,R`$x$ 軸と $y$ 軸の和集合では、$\M{1\\0}+\M{0\\1}=\M{1\\1}$ がどちらの軸にも乗りません。共通部分なら部分空間になります。`);
th('space',R`基底を取り替えると変わるものはどれですか。`,[R`ベクトルの座標`,R`ベクトルそのもの`,R`空間の次元`,R`ベクトルどうしが線形独立かどうか`],R`座標は基底を使った表し方です。表し方を変えても、表されるベクトルや空間の性質は変わりません。`,3);
th('space',R`$\mathbb{R}^3$ の中の原点を通る平面は、何次元の部分空間ですか。`,[R`$2$`,R`$3$`,R`$1$`,R`$0$`],R`平面の中の線形独立な 2 本が基底になります。`);
th('space',R`基底を使ってベクトルを線形結合で表すとき、表し方は何通りありますか。`,[R`ただ 1 通り`,R`2 通り`,R`無数にある`,R`表せないこともある`],R`張るので必ず表せます。線形独立なので係数は 1 組に決まります。この係数が座標です。`,3);
th('space',R`$2\times2$ の実行列の全体は、何次元のベクトル空間ですか。`,[R`$4$`,R`$2$`,R`$3$`,R`$8$`],R`4 つの成分を自由に決められます。1 か所だけが 1 でほかが 0 の行列 4 つが基底になります。`);
ca('space','連立方程式で座標を求める',R`基底 $\vb{b}_1=\M{1\\1}$、$\vb{b}_2=\M{1\\-1}$ での $\M{3\\1}$ の座標 $(c_1,c_2)$ を求めてください。`,[R`$(2,\,1)$`,R`$(1,\,2)$`,R`$(3,\,1)$`,R`$(4,\,2)$`],R`$c_1+c_2=3$、$c_1-c_2=1$ を解いて $c_1=2$、$c_2=1$。$2\M{1\\1}+\M{1\\-1}=\M{3\\1}$ で確かめられます。`);
ca('space','基底変換行列の逆行列を使う',R`基底 $\vb{b}_1=\M{2\\1}$、$\vb{b}_2=\M{1\\1}$ での $\M{4\\3}$ の座標を、$\vb{c}=P^{-1}\vb{p}$ で求めてください。`,[R`$\M{1\\2}$`,R`$\M{2\\1}$`,R`$\M{11\\7}$`,R`$\M{1\\-2}$`],R`$P=\M{2&1\\1&1}$、$\det P=1$ なので $P^{-1}=\M{1&-1\\-1&2}$。$P^{-1}\M{4\\3}=\M{4-3\\-4+6}=\M{1\\2}$。`);
ca('space','部分空間の基底を求める',R`平面 $x+y+z=0$ の基底として正しいものはどれですか。`,[R`$\M{1\\-1\\0},\ \M{1\\0\\-1}$`,R`$\M{1\\1\\1}$`,R`$\M{1\\-1\\0},\ \M{-1\\1\\0}$`,R`$\M{1\\0\\0},\ \M{0\\1\\0},\ \M{0\\0\\1}$`],R`正解の 2 本はどちらも式を満たし、線形独立です。$\M{1\\1\\1}$ は平面に垂直で平面の上にありません。3 番目は 2 本が平行です。4 番目は平面の外のベクトルを含みます。`);
ca('space','次元の公式',R`部分空間 $U,W$ について $\dim U=3$、$\dim W=2$、$\dim(U\cap W)=1$ です。$\dim(U+W)$ を求めてください。`,[R`$4$`,R`$5$`,R`$6$`,R`$3$`],R`$\dim(U+W)=\dim U+\dim W-\dim(U\cap W)=3+2-1=4$。重なっているぶんを 1 回引きます。`);

/* ---------- 固有値 ---------- */
th('eig',R`$\vb{v}$ が $A$ の固有ベクトルであるための条件はどれですか。`,[R`$\vb{v}\ne\vb{0}$ で、ある数 $\lambda$ について $A\vb{v}=\lambda\vb{v}$`,R`ある数 $\lambda$ について $A\vb{v}=\lambda\vb{v}$`,R`$A\vb{v}=\vb{v}$`,R`$A\vb{v}=\vb{0}$`],R`$\vb{v}=\vb{0}$ はどんな $\lambda$ でも式を満たしてしまうので除きます。$\lambda$ は 0 でもかまいません。`,3);
th('eig',R`$A$ が固有値 0 をもつことと同じ条件はどれですか。`,[R`$A$ は正則でない`,R`$A$ は零行列である`,R`$A$ は対角化できない`,R`$A$ は対称行列である`],R`固有値 0 は、$A\vb{v}=\vb{0}$ となる $\vb{0}$ でない $\vb{v}$ があるということです。核が $\{\vb{0}\}$ より大きいので正則ではありません。`,3);
th('eig',R`正方行列の固有値を、複素数の範囲で重複も数えてすべて足すと何になりますか。`,[R`トレース`,R`行列式`,R`ランク`,R`必ず 0`],R`固有多項式を $(\lambda_1-\lambda)\cdots(\lambda_n-\lambda)$ と因数分解し、$\lambda^{n-1}$ の係数を比べると出ます。計算の確かめに使えます。実数の固有値だけを足しても成り立ちません。`,3);
th('eig',R`正方行列の固有値を、複素数の範囲で重複も数えてすべて掛けると何になりますか。`,[R`行列式`,R`トレース`,R`ランク`,R`必ず 1`],R`$\det(A-\lambda I)=(\lambda_1-\lambda)\cdots(\lambda_n-\lambda)$ に $\lambda=0$ を代入すると $\det A=\lambda_1\cdots\lambda_n$ です。`,3);
tf('eig',R`固有ベクトルを 0 でない定数倍したものも、同じ固有値の固有ベクトルである。`,true,R`$A(k\vb{v})=kA\vb{v}=\lambda(k\vb{v})$ です。固有ベクトルは方向で決まります。`);
th('eig',R`平面を 90° 回す行列の実数の固有値について正しいものはどれですか。`,[R`存在しない`,R`$1$ だけ`,R`$1$ と $-1$`,R`$0$ だけ`],R`どのベクトルも向きが変わるので、同じ直線上にとどまるものがありません。固有方程式は $\lambda^2+1=0$ で実数解をもちません。`);
th('eig',R`三角行列の固有値はどれですか。`,[R`対角成分`,R`1 行目の成分`,R`すべての成分`,R`対角成分の逆数`],R`$A-\lambda I$ も三角行列で、行列式は $(a_{11}-\lambda)\cdots(a_{nn}-\lambda)$ です。`);
tf('eig',R`行基本変形をしても固有値は変わらない。`,false,R`$\M{1&0\\0&2}$ の 2 行目を半分にすると固有値は $1,1$ になります。固有値を保つのは $P^{-1}AP$ の形の変形です。`);
th('eig',R`$\lambda$ が $A$ の固有値のとき、$A^2$ の固有値になるものはどれですか。`,[R`$\lambda^2$`,R`$2\lambda$`,R`$\lambda$`,R`$\sqrt{\lambda}$`],R`$A^2\vb{v}=A(\lambda\vb{v})=\lambda^2\vb{v}$ です。固有ベクトルは同じものが使えます。`);
th('eig',R`$A$ が正則で $\lambda$ が $A$ の固有値のとき、$A^{-1}$ の固有値になるものはどれですか。`,[R`$\dfrac1\lambda$`,R`$-\lambda$`,R`$\lambda$`,R`$\lambda^2$`],R`$A\vb{v}=\lambda\vb{v}$ の両辺に $A^{-1}$ を掛けると $\vb{v}=\lambda A^{-1}\vb{v}$ です。$\lambda$ 倍に伸ばす変形の逆は $1/\lambda$ 倍です。`);
th('eig',R`異なる固有値に対する固有ベクトルどうしの関係として正しいものはどれですか。`,[R`線形独立である`,R`直交する`,R`平行である`,R`長さが等しい`],R`一般の行列では線形独立までしか言えません。直交するのは対称行列の場合です。`);
ca('eig','固有方程式を解く',R`$\M{2&1\\1&2}$ の固有値を求めてください。`,[R`$1,\ 3$`,R`$2,\ 2$`,R`$-1,\ 3$`,R`$1,\ 2$`],R`$\det\M{2-\lambda&1\\1&2-\lambda}=(2-\lambda)^2-1=0$ から $2-\lambda=\pm1$。$\lambda=1,3$。`,3);
ca('eig','トレースと行列式を使う',R`和がトレース、積が行列式であることを使って $\M{4&1\\2&3}$ の固有値を求めてください。`,[R`$2,\ 5$`,R`$3,\ 4$`,R`$1,\ 6$`,R`$1,\ 10$`],R`和は $4+3=7$、積は $12-2=10$。足して 7、掛けて 10 になる 2 数は 2 と 5 です。`,3);
ca('eig','固有ベクトルを求める',R`$\M{2&1\\1&2}$ の固有値 $3$ に対する固有ベクトルはどれですか。`,[R`$\M{1\\1}$`,R`$\M{1\\-1}$`,R`$\M{1\\0}$`,R`$\M{2\\1}$`],R`$A-3I=\M{-1&1\\1&-1}$ です。$(A-3I)\vb{v}=\vb{0}$ は $-x+y=0$ なので $\vb{v}=\M{1\\1}$。$\M{1\\-1}$ は固有値 1 の固有ベクトルです。`,3);
ca('eig','三角行列の性質',R`$\M{3&5&1\\0&-1&2\\0&0&4}$ の固有値を求めてください。`,[R`$3,\ -1,\ 4$`,R`$3,\ 5,\ 1$`,R`$1,\ 2,\ 4$`,R`$-12$ だけ`],R`上三角行列なので対角成分がそのまま固有値です。`);
ca('eig','ケーリー・ハミルトンの定理',R`$A=\M{1&2\\3&4}$ のとき、$A^2$ を $A$ と $I$ で表したものはどれですか。`,[R`$5A+2I$`,R`$5A-2I$`,R`$-5A+2I$`,R`$2A+5I$`],R`$\mathrm{tr}\,A=5$、$\det A=-2$ です。定理から $A^2-5A-2I=O$。移項して $A^2=5A+2I$。`);

/* ---------- 対角化 ---------- */
th('diag',R`$P^{-1}AP=D$ と対角化するとき、$P$ の列に並べるものは何ですか。`,[R`$A$ の固有ベクトル`,R`$A$ の固有値`,R`$A$ の列ベクトル`,R`標準基底`],R`固有ベクトルを新しい基底に選ぶと、$A$ はその基底では軸ごとの伸縮だけになります。$P$ はその基底変換行列です。`,3);
th('diag',R`$n$ 次正方行列が対角化できるための条件はどれですか。`,[R`線形独立な固有ベクトルが $n$ 本ある`,R`正則である`,R`固有値に 0 が含まれない`,R`行列式が 1 である`],R`固有ベクトルで基底が作れることが条件です。正則かどうかは関係ありません。零行列は正則ではありませんが、すでに対角行列です。`,3);
tf('diag',R`固有値に重解がある行列は対角化できない。`,false,R`単位行列は固有値が 1 だけですが、すでに対角行列です。重解があっても固有ベクトルが足りていれば対角化できます。`,3);
th('sym',R`実対称行列について正しいものはどれですか。`,[R`固有値はすべて実数で、直交行列で対角化できる`,R`固有値はすべて正である`,R`必ず正則である`,R`対角化できないことがある`],R`実対称行列は必ず直交対角化できます。固有値が負や 0 になることはあります。`);
th('diag',R`相似な行列 $A$ と $B=P^{-1}AP$ で、等しいとは限らないものはどれですか。`,[R`固有ベクトル`,R`固有値`,R`行列式`,R`トレース`],R`相似な行列は同じ変換を別の基底で表したものです。固有値などの基底によらない量は等しく、固有ベクトルの成分は基底によって変わります。`);
th('diag',R`$A=PDP^{-1}$ のとき $A^n$ と等しいものはどれですか。`,[R`$PD^nP^{-1}$`,R`$P^nD^nP^{-n}$`,R`$PDP^{-n}$`,R`$D^n$`],R`$PDP^{-1}\cdot PDP^{-1}\cdots$ と並べると、間の $P^{-1}P$ が $I$ になって消えます。`,3);
th('diag',R`次のうち対角化できない行列はどれですか。`,[R`$\M{1&1\\0&1}$`,R`$\M{1&0\\0&1}$`,R`$\M{2&0\\0&3}$`,R`$\M{0&1\\1&0}$`],R`$\M{1&1\\0&1}$ は固有値が 1 だけで、固有ベクトルは $\M{1\\0}$ の方向しかありません。2 本そろわないので対角化できません。`);
th('sym',R`対称行列 $A$ が正定値であることと同じ条件はどれですか。`,[R`固有値がすべて正`,R`成分がすべて正`,R`行列式が正`,R`トレースが正`],R`直交対角化すると $\vb{x}^{\mathsf T}A\vb{x}=\lambda_1y_1^2+\cdots+\lambda_ny_n^2$ と書けます。これがいつも正になるのは固有値が全部正のときです。`);
ca('diag','固有値と固有ベクトルから P と D を作る',R`$A=\M{2&1\\1&2}$ を $P^{-1}AP=D$ と対角化する組として正しいものはどれですか。`,[R`$P=\M{1&1\\1&-1},\ D=\M{3&0\\0&1}$`,R`$P=\M{1&1\\1&-1},\ D=\M{1&0\\0&3}$`,R`$P=\M{1&0\\0&1},\ D=\M{3&0\\0&1}$`,R`$P=\M{1&1\\1&-1},\ D=\M{2&0\\0&2}$`],R`固有値 3 の固有ベクトルが $\M{1\\1}$、固有値 1 の固有ベクトルが $\M{1\\-1}$ です。$P$ の 1 列目に $\M{1\\1}$ を置いたら、$D$ の 1 番目は 3 にします。`,3);
ca('diag','対角化を使ったべき乗',R`$A=\M{2&1\\1&2}$ のとき $A^3$ を求めてください。固有値は $3$ と $1$ です。`,[R`$\M{14&13\\13&14}$`,R`$\M{8&1\\1&8}$`,R`$\M{27&0\\0&1}$`,R`$\M{13&14\\14&13}$`],R`$P=\M{1&1\\1&-1}$、$P^{-1}=\dfrac12\M{1&1\\1&-1}$、$D^3=\M{27&0\\0&1}$。$PD^3P^{-1}=\dfrac12\M{27+1&27-1\\27-1&27+1}=\M{14&13\\13&14}$。`,3);
ca('sym','二次形式の行列を作る',R`二次形式 $2x^2+6xy+5y^2$ を $\vb{x}^{\mathsf T}A\vb{x}$ と書くときの対称行列 $A$ はどれですか。`,[R`$\M{2&3\\3&5}$`,R`$\M{2&6\\6&5}$`,R`$\M{2&6\\0&5}$`,R`$\M{2&0\\0&5}$`],R`$x^2$ と $y^2$ の係数を対角に置きます。$xy$ の係数 6 は半分ずつに分けて、対角の外の 2 か所に 3 を置きます。`);
ca('sym','首座小行列式で正定値を判定',R`次の対称行列のうち正定値であるものはどれですか。`,[R`$\M{2&3\\3&5}$`,R`$\M{1&2\\2&1}$`,R`$\M{-1&0\\0&2}$`,R`$\M{1&1\\1&1}$`],R`左上から順に取った行列式がすべて正なら正定値です。正解は $2>0$、$10-9=1>0$。ほかは行列式が $-3$、左上が $-1$、行列式が $0$ で条件を満たしません。`);

/* ---------- 直交化・最小二乗・特異値分解 ---------- */
th('orth',R`正規直交基底 $\vb{u}_1,\dots,\vb{u}_n$ でのベクトル $\vb{p}$ の座標はどう求まりますか。`,[R`内積 $\vb{p}\cdot\vb{u}_i$`,R`外積 $\vb{p}\times\vb{u}_i$`,R`$\vb{p}$ の第 $i$ 成分`,R`$\|\vb{p}-\vb{u}_i\|$`],R`$\vb{p}=c_1\vb{u}_1+\cdots+c_n\vb{u}_n$ の両辺で $\vb{u}_i$ との内積を取ると、ほかの項は直交して消え、$c_i$ だけが残ります。`);
th('orth',R`グラム・シュミットの直交化で、2 本目のベクトルに対して最初に行う操作はどれですか。`,[R`1 本目の方向への正射影を引く`,R`1 本目を足す`,R`長さを 1 にする`,R`1 本目との外積を取る`],R`まず 1 本目と同じ方向の成分を取り除いて直交させます。長さを 1 にするのはそのあとです。`,3);
th('orth',R`最小二乗法の正規方程式はどれですか。`,[R`$A^{\mathsf T}A\vb{x}=A^{\mathsf T}\vb{b}$`,R`$AA^{\mathsf T}\vb{x}=\vb{b}$`,R`$A\vb{x}=A^{\mathsf T}\vb{b}$`,R`$A^{\mathsf T}\vb{x}=\vb{b}$`],R`誤差 $\vb{b}-A\vb{x}$ が $A$ のすべての列と直交する、という条件 $A^{\mathsf T}(\vb{b}-A\vb{x})=\vb{0}$ を書き直したものです。`,3);
th('orth',R`最小二乗解 $\hat{\vb{x}}$ について、$A\hat{\vb{x}}$ は何になっていますか。`,[R`$\vb{b}$ の $A$ の列空間への正射影`,R`$\vb{b}$ そのもの`,R`$A$ の核への正射影`,R`零ベクトル`],R`$A\vb{x}$ で届くのは列空間の中だけです。その中で $\vb{b}$ にいちばん近い点は、$\vb{b}$ から垂直に下ろした足です。`);
th('svd',R`行列 $A$ の特異値はどのように定義されますか。`,[R`$A^{\mathsf T}A$ の固有値の 0 以上の平方根`,R`$A$ の固有値の絶対値`,R`$A$ の対角成分`,R`$A+A^{\mathsf T}$ の固有値`],R`$A^{\mathsf T}A$ は対称で固有値が 0 以上なので、平方根が取れます。$A$ 自身の固有値とは別のものです。`);
tf('svd',R`特異値分解は正方行列にしか使えない。`,false,R`どんな型の行列にも使えます。そこが対角化との大きな違いです。`);
th('svd',R`0 でない特異値の個数と等しいものはどれですか。`,[R`ランク`,R`行列式`,R`トレース`,R`列の数`],R`$\Sigma$ の 0 でない対角成分の数が、伸びて残る方向の数です。これは像の次元です。`);
th('orth',R`部分空間への射影行列 $P$ が必ず満たす式はどれですか。`,[R`$P^2=P$`,R`$P^2=I$`,R`$P^2=O$`,R`$P^{-1}=P$`],R`一度射影したものをもう一度射影しても動きません。`);
th('orth',R`直交行列の行列式になりうる値はどれですか。`,[R`$1$ か $-1$`,R`$0$`,R`正の数すべて`,R`どんな実数にもなる`],R`$Q^{\mathsf T}Q=I$ の行列式を取ると $(\det Q)^2=1$ です。$1$ が回転、$-1$ が鏡映を含む場合です。`);
ca('orth','グラム・シュミットの直交化',R`$\vb{a}_1=\M{3\\4}$、$\vb{a}_2=\M{1\\0}$ をこの順にグラム・シュミットで直交化します。2 本目の $\vb{u}_2$ を求めてください。`,[R`$\M{4/5\\-3/5}$`,R`$\M{3/5\\4/5}$`,R`$\M{1\\0}$`,R`$\M{16/25\\-12/25}$`],R`$\vb{u}_1=\M{3/5\\4/5}$。$\vb{a}_2\cdot\vb{u}_1=\dfrac35$ なので $\vb{w}_2=\M{1\\0}-\dfrac35\M{3/5\\4/5}=\M{16/25\\-12/25}$。長さは $\dfrac45$ で、割ると $\M{4/5\\-3/5}$。`,3);
ca('orth','正規方程式',R`原点を通る直線 $y=ax$ を 2 点 $(1,1)$、$(2,3)$ に最小二乗法で当てはめます。$a$ を求めてください。`,[R`$\dfrac75$`,R`$2$`,R`$\dfrac32$`,R`$\dfrac43$`],R`$A=\M{1\\2}$、$\vb{b}=\M{1\\3}$ です。$A^{\mathsf T}A=5$、$A^{\mathsf T}\vb{b}=1+6=7$。$5a=7$ から $a=\dfrac75$。`);
ca('svd','対角行列の特異値',R`$\M{3&0\\0&-2}$ の特異値を求めてください。`,[R`$3,\ 2$`,R`$3,\ -2$`,R`$9,\ 4$`,R`$1,\ 6$`],R`$A^{\mathsf T}A=\M{9&0\\0&4}$ の固有値は 9 と 4。平方根を取って 3 と 2。特異値は負になりません。固有値は $3$ と $-2$ です。`);
ca('svd','AᵀA の固有値から求める',R`$A=\M{1&1\\0&0}$ の特異値を求めてください。`,[R`$\sqrt2,\ 0$`,R`$1,\ 0$`,R`$2,\ 0$`,R`$1,\ 1$`],R`$A^{\mathsf T}A=\M{1&1\\1&1}$ の固有値は、和が 2、積が 0 なので 2 と 0。平方根は $\sqrt2$ と $0$。$A$ の固有値は 1 と 0 で、特異値とは違います。`);
ca('orth','直交行列の判定 (QᵀQ = I)',R`次のうち直交行列はどれですか。`,[R`$\dfrac{1}{\sqrt2}\M{1&-1\\1&1}$`,R`$\M{1&1\\0&1}$`,R`$\M{2&0\\0&1/2}$`,R`$\M{1&1\\1&-1}$`],R`列どうしが直交し、どの列も長さ 1 であることを確かめます。4 番目は列が直交していますが長さが $\sqrt2$ です。3 番目は行列式が 1 ですが長さを変えます。`);
ca('orth','射影行列の公式',R`$\M{1\\1}$ の方向の直線への正射影を表す行列を求めてください。`,[R`$\dfrac12\M{1&1\\1&1}$`,R`$\M{1&1\\1&1}$`,R`$\dfrac12\M{1&-1\\-1&1}$`,R`$\M{1&0\\0&1}$`],R`$\vb{a}$ 方向への射影行列は $\dfrac{\vb{a}\vb{a}^{\mathsf T}}{\vb{a}^{\mathsf T}\vb{a}}$ です。$\vb{a}\vb{a}^{\mathsf T}=\M{1&1\\1&1}$、$\vb{a}^{\mathsf T}\vb{a}=2$。2 回掛けても変わらないことで確かめられます。`);

/* ---------- 追加: 理論 ---------- */
tf('vec',R`$\|\vb{a}\|=0$ ならば $\vb{a}=\vb{0}$ である。`,true,R`$\|\vb{a}\|^2=a_1^2+\cdots+a_n^2$ の各項は 0 以上なので、和が 0 になるのは全成分が 0 のときだけです。`);
th('vec',R`$\vb{a}=\M{a_1\\a_2},\ \vb{b}=\M{b_1\\b_2}$ で、一方が他方のスカラー倍であることと同じ条件はどれですか。`,[R`$a_1b_2-a_2b_1=0$`,R`$a_1b_1+a_2b_2=0$`,R`$\|\vb{a}\|=\|\vb{b}\|$`,R`$a_1=b_1$ かつ $a_2=b_2$`],R`2 本が同じ直線上にあるとき、成分の比が等しくなります。2 番目は直交の条件、3 番目は長さが等しいだけ、4 番目は 2 本が等しいという条件で、スカラー倍の一部しか含みません。`);
th('comb',R`$\vb{v}_1,\dots,\vb{v}_k$ が線形独立で、$\vb{w}$ がそれらの張る空間に含まれないとき、$\vb{v}_1,\dots,\vb{v}_k,\vb{w}$ について正しいものはどれですか。`,[R`必ず線形独立`,R`必ず線形従属`,R`$\vb{w}$ が $\vb{v}_1$ と直交するときだけ線形独立`,R`$\vb{w}$ の長さによって決まる`],R`$c_1\vb{v}_1+\cdots+c_k\vb{v}_k+c\vb{w}=\vb{0}$ で $c\ne0$ なら $\vb{w}$ が $\vb{v}_i$ の線形結合になり、仮定に反します。よって $c=0$ で、残りは $\vb{v}_i$ の独立性から全部 0 です。直交や長さは関係ありません。`,3);
th('comb',R`$\vb{v}_1,\vb{v}_2,\vb{v}_3\in\mathbb{R}^3$ を列に並べた行列を $A$ とします。3 本が線形独立であることと同じ条件でないものはどれですか。`,[R`$A$ の成分に 0 が 1 つもない`,R`$\det A\ne0$`,R`$A\vb{x}=\vb{0}$ の解は $\vb{x}=\vb{0}$ だけ`,R`3 本が $\mathbb{R}^3$ を張る`],R`単位行列は 0 を含みますが列は独立です。$A\vb{x}=\vb{0}$ は $x_1\vb{v}_1+x_2\vb{v}_2+x_3\vb{v}_3=\vb{0}$ そのものです。$\mathbb{R}^3$ の 3 本では「独立」と「張る」が同じ条件になります。`);
th('dot',R`$\vb{0}$ でないベクトル $\vb{u}_1,\dots,\vb{u}_k$ が互いに直交しています。必ず言えることはどれですか。`,[R`線形独立である`,R`線形従属である`,R`$k\le2$ である`,R`長さがすべて等しい`],R`$c_1\vb{u}_1+\cdots+c_k\vb{u}_k=\vb{0}$ と $\vb{u}_i$ の内積を取ると $c_i\|\vb{u}_i\|^2=0$ です。$\vb{u}_i\ne\vb{0}$ なので $c_i=0$。「$\vb{0}$ でない」を外すと成り立ちません。`,3);
th('dot',R`$\vb{a}\cdot\vb{b}=0$ のとき $\|\vb{a}+\vb{b}\|^2$ と等しいものはどれですか。`,[R`$\|\vb{a}\|^2+\|\vb{b}\|^2$`,R`$(\|\vb{a}\|+\|\vb{b}\|)^2$`,R`$\|\vb{a}\|^2-\|\vb{b}\|^2$`,R`$0$`],R`$\|\vb{a}+\vb{b}\|^2=\|\vb{a}\|^2+2\vb{a}\cdot\vb{b}+\|\vb{b}\|^2$ で、真ん中が 0 です (三平方の定理)。2 番目は $2\|\vb{a}\|\|\vb{b}\|$ だけ大きく、同じ向きのときの値です。`);
th('dot',R`$\mathbb{R}^3$ で $\|\vb{a}\times\vb{b}\|$ が表すものはどれですか。`,[R`$\vb{a},\vb{b}$ を 2 辺とする平行四辺形の面積`,R`$\vb{a},\vb{b}$ を 2 辺とする三角形の面積`,R`$|\vb{a}\cdot\vb{b}|$`,R`$\|\vb{a}\|+\|\vb{b}\|$`],R`$\|\vb{a}\times\vb{b}\|=\|\vb{a}\|\|\vb{b}\|\sin\theta$ で、底辺と高さの積です。三角形はその半分です。内積は $\cos\theta$ を使うので別の量です。`);
th('dot',R`コーシー・シュワルツの不等式の証明で使う事実はどれですか。`,[R`どんな実数 $t$ でも $\|\vb{a}+t\vb{b}\|^2\ge0$`,R`どんな角 $\theta$ でも $|\cos\theta|\le1$`,R`$\vb{a}\cdot\vb{b}=\vb{b}\cdot\vb{a}$ だけ`,R`$\|\vb{a}\|=\|\vb{b}\|$`],R`左辺は $t$ の 2 次式で、いつも 0 以上なので判別式が 0 以下になります。なす角は、この不等式が成り立つことを使って定義するので、$\cos\theta$ を証明に使うと順序が逆になります。`);
th('map',R`線形写像 $f:\mathbb{R}^2\to\mathbb{R}^2$ を 1 つに決めるのに十分な情報はどれですか。`,[R`基底 $\vb{b}_1,\vb{b}_2$ の行き先 $f(\vb{b}_1),f(\vb{b}_2)$`,R`$f(\vb{0})$ の値`,R`$\vb{0}$ でないベクトル 1 本の行き先`,R`$f$ が原点を原点に移すこと`],R`どの $\vb{x}=c_1\vb{b}_1+c_2\vb{b}_2$ についても $f(\vb{x})=c_1f(\vb{b}_1)+c_2f(\vb{b}_2)$ と決まります。$f(\vb{0})=\vb{0}$ はどの線形写像でも同じなので情報になりません。1 本だけでは 2 次元ぶんを決められません。`,3);
th('map',R`次のうち線形写像であるものはどれですか。`,[R`$f(x,y)=(x-y,\;3x)$`,R`$f(x,y)=(x^2,\;y)$`,R`$f(x,y)=(xy,\;0)$`,R`$f(x,y)=(|x|,\;y)$`],R`4 つとも原点を原点に移すので、それだけでは判定できません。$x^2$ は $f(2,0)=(4,0)\ne2f(1,0)$、$xy$ は $f(2,2)=(4,0)\ne2f(1,1)$、$|x|$ は $f(-1,0)=(1,0)\ne-f(1,0)$ です。`,3);
th('map',R`行列 $A$ の成分 $a_{23}$ はどこにある数ですか。`,[R`上から 2 番目の行、左から 3 番目の列`,R`上から 3 番目の行、左から 2 番目の列`,R`2 番目の対角成分`,R`左上から数えて 23 番目`],R`添え字は「行、列」の順です。$m\times n$ 行列の型の書き方と同じ順番です。`);
th('prod',R`$n$ 次正方行列 $A,B$ が $AB=I$ を満たすとき、正しいものはどれですか。`,[R`$BA=I$ も成り立つ`,R`$BA=I$ とは限らない`,R`$A=B$`,R`$A=I$`],R`$B\vb{x}=\vb{0}$ なら $\vb{x}=AB\vb{x}=\vb{0}$ なので $B$ は正則で、$A=ABB^{-1}=B^{-1}$。よって $BA=I$ です。正方でないと成り立ちません。$A=\M{1&0}$、$B=\M{1\\0}$ なら $AB=(1)$ ですが $BA=\M{1&0\\0&0}$ です。`,3);
tf('prod',R`$A=\M{1&1\\0&1}$、$B=\M{1&0\\1&1}$ について $AB=BA$ である。`,false,R`$AB=\M{2&1\\1&1}$、$BA=\M{1&1\\1&2}$ で異なります。`);
th('prod',R`$A$ が正則のとき $(A^{\mathsf T})^{-1}$ と等しいものはどれですか。`,[R`$(A^{-1})^{\mathsf T}$`,R`$A^{-1}$`,R`$A^{\mathsf T}$`,R`$-A^{\mathsf T}$`],R`$A^{\mathsf T}(A^{-1})^{\mathsf T}=(A^{-1}A)^{\mathsf T}=I$ です。$A^{-1}$ と一致するのは $A$ が対称のときだけです。`);
th('prod',R`正方行列 $A,B$ について $(A+B)(A-B)=A^2-B^2$ が成り立つための条件はどれですか。`,[R`$AB=BA$`,R`$A,B$ がどちらも正則`,R`$A,B$ がどちらも対称`,R`条件なしでいつも成り立つ`],R`展開すると $A^2-AB+BA-B^2$ です。真ん中の 2 項が消えるのは $AB=BA$ のときだけです。数の公式を行列に使うときは可換かどうかを確かめます。`);
th('sys',R`$A\vb{x}=\vb{b}$ が異なる 2 つの解 $\vb{x}_1,\vb{x}_2$ をもつとき、正しいものはどれですか。`,[R`解は無数にある`,R`解はちょうど 2 つ`,R`$\vb{b}=\vb{0}$ である`,R`$A$ は正則である`],R`$A(\vb{x}_2-\vb{x}_1)=\vb{0}$ なので、どの $t$ でも $\vb{x}_1+t(\vb{x}_2-\vb{x}_1)$ が解です。正則なら解は 1 つのはずです。`,3);
th('sys',R`$\vb{b}\ne\vb{0}$ のとき、$A\vb{x}=\vb{b}$ の解全体の集合について正しいものはどれですか。`,[R`部分空間ではない`,R`必ず部分空間である`,R`必ず空集合である`,R`必ず 1 点である`],R`$A\vb{0}=\vb{0}\ne\vb{b}$ なので $\vb{0}$ を含みません。解があるときは、特殊解に核のベクトルを足した形、つまり部分空間を平行移動した形になります。`);
th('sys',R`$m\times n$ 行列 $A$ について $A\vb{x}=\vb{b}$ が解をもつとき、解がただ 1 つであるための条件はどれですか。`,[R`$\mathrm{rank}\,A=n$`,R`$\mathrm{rank}\,A=m$`,R`$m=n$`,R`$\vb{b}=\vb{0}$`],R`自由変数の個数は $n-\mathrm{rank}\,A$ で、0 なら解は 1 つです。式の多い方程式でも 1 つに決まることがあります。$\mathrm{rank}\,A=m$ は「どんな $\vb{b}$ でも解がある」条件です。`,3);
th('sys',R`行列を行基本変形で簡約階段行列に直します。結果について正しいものはどれですか。`,[R`変形の順序によらず、ただ 1 つに決まる`,R`変形の順序によって変わることがある`,R`正方行列のときだけ 1 つに決まる`,R`必ず単位行列になる`],R`階段行列は直し方によって変わりますが、簡約階段行列は 1 つに決まります。そのため 0 でない行の数、つまりランクも変形の仕方によりません。単位行列になるのは正則行列のときです。`);
th('sys',R`基本行列を行列 $A$ に左から掛けると何が起きますか。`,[R`$A$ に対応する行基本変形が行われる`,R`$A$ に対応する列の変形が行われる`,R`$A$ が転置される`,R`$A$ が逆行列になる`],R`基本行列は単位行列に行基本変形を 1 回行ったものです。左から掛けると行に、右から掛けると列に、同じ変形が行われます。`);
th('det',R`正方行列 $A$ について、$\det(A^{\mathsf T})$ と $\det A$ の関係はどれですか。`,[R`常に等しい`,R`符号が逆`,R`逆数どうし`,R`一般には無関係`],R`常に等しいので、行について成り立つ性質が列についてもそのまま成り立ちます。`,3);
th('det',R`3 次正方行列 $A$ の 1 行目だけを 2 倍した行列 $B$ について $\det B$ はどれですか。`,[R`$2\det A$`,R`$8\det A$`,R`$6\det A$`,R`$\det A$`],R`行列式は 1 つの行について線形なので、1 行だけ 2 倍すると 2 倍です。全部の行を 2 倍した $\det(2A)=8\det A$ と区別します。`,3);
th('det',R`$n$ 次正方行列 $A$ と余因子行列 $\mathrm{adj}\,A$ について、常に成り立つ式はどれですか。`,[R`$A\,\mathrm{adj}\,A=(\det A)\,I$`,R`$A\,\mathrm{adj}\,A=I$`,R`$\mathrm{adj}\,A=A^{-1}$`,R`$A\,\mathrm{adj}\,A=O$`],R`対角成分は余因子展開そのものです。対角の外は「同じ行が 2 つある行列」の展開になるので 0 です。$\det A=0$ でも成り立ちます。2 番目と 3 番目は $\det A=1$ のときだけです。`);
th('det',R`3 次の交代行列 $A$ ($A^{\mathsf T}=-A$) の行列式について正しいものはどれですか。`,[R`必ず 0`,R`必ず正`,R`必ず負`,R`必ず 1`],R`$\det A=\det A^{\mathsf T}=\det(-A)=(-1)^3\det A$ なので $\det A=0$ です。奇数次で成り立つ性質で、2 次の $\M{0&1\\-1&0}$ は行列式が 1 です。`);
th('det',R`「各行について線形」「2 つの行が等しければ 0」を満たす関数を行列式ただ 1 つに決めるには、もう 1 つどの条件が必要ですか。`,[R`$\det I=1$`,R`$\det O=0$`,R`$\det A^{\mathsf T}=\det A$`,R`$\det(AB)=\det A\det B$`],R`2 つの性質だけなら行列式の定数倍もすべて満たすので、$\det I=1$ で倍率を固定します。$\det O=0$ は線形性から出ます。残りの 2 つは定義から導かれる定理です。`);
th('det',R`$n$ 次の行列式の定義式 $\sum_{\sigma}\mathrm{sgn}(\sigma)a_{1\sigma(1)}\cdots a_{n\sigma(n)}$ には、項がいくつありますか。`,[R`$n!$ 個`,R`$n^2$ 個`,R`$2^n$ 個`,R`$2n$ 個`],R`$n$ 文字の置換 1 つにつき項が 1 つあり、置換は $n!$ 個です。3 次なら 6 個、4 次なら 24 個です。サラスの方法が 4 次で使えないのは、斜めの積が 8 個しか作れないからです。`);
th('det',R`$\det A\ne0$ のとき、余因子行列 $\mathrm{adj}\,A$ を使って $A^{-1}$ を表す式はどれですか。`,[R`$\dfrac{1}{\det A}\,\mathrm{adj}\,A$`,R`$(\det A)\,\mathrm{adj}\,A$`,R`$\mathrm{adj}\,A$`,R`$\dfrac{1}{\det A}\,(\mathrm{adj}\,A)^{\mathsf T}$`],R`$A\,\mathrm{adj}\,A=(\det A)I$ の両辺を $\det A$ で割った式です。余因子行列は余因子を並べてから転置したものなので、もう一度転置すると誤りになります。`);
th('rank',R`行列 $A$ に行基本変形をして $B$ を得ました。$A$ と $B$ で一致するとは限らないものはどれですか。`,[R`列空間`,R`核`,R`行空間`,R`ランク`],R`$\M{1&1\\1&1}\to\M{1&1\\0&0}$ で、列空間は $\M{1\\1}$ の直線から $\M{1\\0}$ の直線に変わります。次元は変わりません。行は互いの線形結合になるだけなので行空間は変わらず、解も変わらないので核も変わりません。`,3);
th('rank',R`$n$ 次正方行列が表す線形変換について、単射であることと同じ条件はどれですか。`,[R`全射である`,R`対称行列である`,R`固有値がすべて正`,R`零行列でない`],R`次元定理 $n=\mathrm{rank}\,A+\dim\mathrm{Ker}\,A$ から、核が $\{\vb{0}\}$ であることとランクが $n$ であることが同じになります。正方でないと成り立ちません。`,3);
th('rank',R`$A$ を $m\times n$、$B$ を $n\times p$ 行列とします。常に成り立つものはどれですか。`,[R`$\mathrm{rank}(AB)\le\min(\mathrm{rank}\,A,\mathrm{rank}\,B)$`,R`$\mathrm{rank}(AB)=\mathrm{rank}\,A\cdot\mathrm{rank}\,B$`,R`$\mathrm{rank}(AB)=\mathrm{rank}\,A+\mathrm{rank}\,B$`,R`$\mathrm{rank}(AB)\ge\max(\mathrm{rank}\,A,\mathrm{rank}\,B)$`],R`$AB$ の像は $A$ の像に含まれるので $\mathrm{rank}\,A$ 以下です。また $B$ の像を $A$ で移しても次元は増えないので $\mathrm{rank}\,B$ 以下です。$\M{1&0\\0&0}\M{0&0\\0&1}=O$ がほかの選択肢の反例です。`);
tf('rank',R`正方行列 $A$ について、$A\vb{x}=\vb{0}$ が $\vb{x}=\vb{0}$ 以外の解をもつことと、$\det A=0$ は同じ条件である。`,true,R`$\vb{0}$ 以外の解があることは、核が $\{\vb{0}\}$ より大きいこと、ランクが $n$ より小さいこと、$\det A=0$ のどれとも同じです。`,3);
th('rank',R`線形変換の表現行列が $A$ のとき、基底変換行列 $P$ で基底を取り替えたあとの表現行列はどれですか。`,[R`$P^{-1}AP$`,R`$AP$`,R`$P^{\mathsf T}AP$`,R`$A$ のまま変わらない`],R`新しい座標 $\vb{c}$ を $P$ で元の座標に直し、$A$ を掛け、$P^{-1}$ で新しい座標に戻します。$P^{\mathsf T}AP$ と一致するのは $P$ が直交行列のときだけです。`,3);
th('rank',R`表現行列の列に並んでいるものは何ですか。`,[R`各基底ベクトルの行き先を、行き先側の基底での座標で書いたもの`,R`各基底ベクトルそのもの`,R`固有ベクトル`,R`核の基底`],R`第 4 章の「列は基底ベクトルの行き先」を、標準基底以外の基底に広げたものです。基底を変えると同じ写像でも表現行列は変わります。`);
th('space',R`$\mathbb{R}^2$ の部分集合のうち、部分空間であるものはどれですか。`,[R`$\{(x,y)\mid 2x-3y=0\}$`,R`$\{(x,y)\mid x\ge0,\ y\ge0\}$`,R`$\{(x,y)\mid xy=0\}$`,R`$\{(x,y)\mid x^2+y^2\le1\}$`],R`2 番目は $-1$ 倍で外に出ます。3 番目は $(1,0)+(0,1)$ が外に出ます。4 番目は 2 倍で外に出ます。原点を含むだけでは部分空間になりません。`,3);
th('space',R`$\mathbb{R}^3$ の線形独立な 3 本のベクトルについて正しいものはどれですか。`,[R`必ず $\mathbb{R}^3$ の基底になる`,R`全体を張るかどうか別に確かめる必要がある`,R`互いに直交しているときだけ基底になる`,R`長さが 1 のときだけ基底になる`],R`張らないとすると、張る空間の外のベクトルを加えて線形独立な 4 本ができ、次元が 3 であることに反します。$n$ 次元の空間では、線形独立な $n$ 本は基底です。`);
th('space',R`実係数の多項式の全体が作るベクトル空間の次元について正しいものはどれですか。`,[R`有限個のベクトルでは張れない (無限次元)`,R`$1$`,R`$2$`,R`次数の最大値に等しい`],R`有限個の多項式の線形結合では、その中の最大の次数より高い次数の多項式が作れません。次数を $n$ 以下に限れば $n+1$ 次元です。`);
tf('eig',R`実数を成分とする正方行列の固有値は、必ず実数である。`,false,R`90° 回転 $\M{0&-1\\1&0}$ の固有値は $\pm i$ です。実行列の実数でない固有値は共役の組で現れます。必ず実数になるのは実対称行列です。`,3);
th('eig',R`正方行列 $A$ と $A^{\mathsf T}$ で必ず一致するものはどれですか。`,[R`固有値`,R`固有ベクトル`,R`固有空間`,R`列空間`],R`$\det(A^{\mathsf T}-\lambda I)=\det((A-\lambda I)^{\mathsf T})=\det(A-\lambda I)$ です。$A=\M{1&1\\0&2}$ の固有値 1 の固有ベクトルは $\M{1\\0}$、$A^{\mathsf T}$ では $\M{1\\-1}$ で異なります。`);
th('eig',R`$A^2=O$ を満たす正方行列 $A$ の固有値として考えられるものはどれですか。`,[R`$0$ だけ`,R`$1$ だけ`,R`$0$ と $1$`,R`$1$ と $-1$`],R`$A\vb{v}=\lambda\vb{v}$ なら $\vb{0}=A^2\vb{v}=\lambda^2\vb{v}$ で、$\vb{v}\ne\vb{0}$ から $\lambda=0$ です。`);
th('eig',R`1 つの固有値の代数的重複度と幾何的重複度の関係として、常に成り立つものはどれですか。`,[R`幾何的重複度 $\le$ 代数的重複度`,R`幾何的重複度 $\ge$ 代数的重複度`,R`いつも等しい`,R`和が $n$ になる`],R`等しくなるとは限りません。$\M{1&1\\0&1}$ の固有値 1 は代数的重複度 2、幾何的重複度 1 です。すべての固有値で等しいことが、対角化できる条件です。`);
th('diag',R`$n$ 次正方行列 $A$ が対角化できることと同じ条件はどれですか。固有値は複素数の範囲で考えます。`,[R`各固有値で幾何的重複度と代数的重複度が等しい`,R`固有値がすべて異なる`,R`$\det A\ne0$`,R`固有値の和がトレースに等しい`],R`固有空間の次元の和が $n$ になる、ということです。「すべて異なる」は十分条件ですが必要ではありません。単位行列がその例です。最後の性質はどの行列でも成り立ちます。`,3);
tf('diag',R`固有多項式が等しい 2 つの正方行列は、必ず相似である。`,false,R`$I$ と $\M{1&1\\0&1}$ の固有多項式はどちらも $(1-\lambda)^2$ ですが、$P^{-1}IP=I$ なので $I$ と相似な行列は $I$ だけです。`);
th('diag',R`正方行列 $A$ が $A^2=O$ かつ $A\ne O$ を満たすとき、正しいものはどれですか。`,[R`対角化できない`,R`必ず対角化できる`,R`正則である`,R`対称行列である`],R`固有値は 0 だけなので、対角化できるなら $P^{-1}AP=O$ となり $A=O$ で矛盾します。$\det A^2=0$ なので正則でもありません。`);
th('diag',R`$\M{2&0\\0&2}$ の最小多項式はどれですか。`,[R`$x-2$`,R`$(x-2)^2$`,R`$x^2-4$`,R`$x$`],R`$A-2I=O$ なので 1 次式 $x-2$ で $O$ になります。固有多項式は $(x-2)^2$ ですが、最小多項式はそれを割り切るもっと次数の低い式になることがあります。重解をもたないので対角化できる行列です。`);
th('diag',R`2 次正方行列で、固有値 2 が 2 重、固有空間が 1 次元のものがあります。そのジョルダン標準形はどれですか。`,[R`$\M{2&1\\0&2}$`,R`$\M{2&0\\0&2}$`,R`$\M{2&1\\1&2}$`,R`$\M{1&2\\0&1}$`],R`固有ベクトルが 1 方向しかないので、2 次のジョルダン細胞が 1 つになります。$\M{2&0\\0&2}$ は固有空間が 2 次元の場合です。`);
th('orth',R`内積の条件に含まれないものはどれですか。`,[R`$(\vb{u},\vb{v})=0$ ならば $\vb{u}=\vb{0}$ または $\vb{v}=\vb{0}$`,R`$(\vb{u},\vb{v})=(\vb{v},\vb{u})$`,R`各変数について線形である`,R`$(\vb{v},\vb{v})\ge0$ で、等号は $\vb{v}=\vb{0}$ のときだけ`],R`1 番目は成り立ちません。直交する $\vb{0}$ でないベクトルはいくらでもあります。残りの 3 つが内積の条件です。`);
th('orth',R`$m\times n$ 実行列 $A$ の核と行空間の関係として正しいものはどれですか。`,[R`互いに相手の直交補空間である`,R`一致する`,R`核は行空間に含まれる`,R`一般には関係がない`],R`$A\vb{x}=\vb{0}$ は「$\vb{x}$ と各行の内積が 0」という意味です。次元も $n-r$ と $r$ で、合わせて $n$ になります。`);
th('orth',R`直交行列 $Q$ の固有値 $\lambda$ (複素数の範囲) について必ず言えることはどれですか。`,[R`$|\lambda|=1$`,R`$\lambda=1$`,R`$\lambda$ は $0$ か $1$`,R`$\lambda>0$`],R`$Q$ は長さを保つので $\|Q\vb{v}\|=|\lambda|\|\vb{v}\|=\|\vb{v}\|$ です。回転なら絶対値 1 の複素数、鏡映なら $-1$ も現れます。0 か 1 になるのは射影行列です。`);
th('orth',R`$m\times n$ 行列 $Q$ ($m>n$) の列が正規直交であるとき、正しいものはどれですか。`,[R`$Q^{\mathsf T}Q=I_n$ だが $QQ^{\mathsf T}\ne I_m$`,R`$QQ^{\mathsf T}=I_m$ である`,R`$Q$ は直交行列である`,R`$Q^{\mathsf T}=Q^{-1}$ である`],R`$QQ^{\mathsf T}$ はランク $n$ の、列空間への射影行列です。$Q=\M{1&0\\0&1\\0&0}$ なら $QQ^{\mathsf T}=\M{1&0&0\\0&1&0\\0&0&0}$ です。正方でないので逆行列は考えられません。`);
th('orth',R`正規方程式 $A^{\mathsf T}A\vb{x}=A^{\mathsf T}\vb{b}$ の解がただ 1 つに決まるための条件はどれですか。`,[R`$A$ の列が線形独立`,R`$A$ が正方行列`,R`$\vb{b}$ が $A$ の列空間に入る`,R`$A^{\mathsf T}A$ の成分がすべて正`],R`$A^{\mathsf T}A$ の核は $A$ の核と同じなので、列が線形独立であることと $A^{\mathsf T}A$ が正則であることが同じになります。正規方程式は必ず解をもちますが、1 つに決まるかは列の独立性で決まります。`);
th('orth',R`$P$ が部分空間 $W$ への正射影を表す行列のとき、$I-P$ が表すものはどれですか。`,[R`$W^\perp$ への正射影`,R`$W$ への正射影`,R`恒等変換`,R`すべてを $\vb{0}$ に移す写像`],R`$\vb{x}=P\vb{x}+(I-P)\vb{x}$ と分けると、後ろが $W$ に垂直な成分です。$(I-P)^2=I-2P+P^2=I-P$ も確かめられます。`);
th('orth',R`$\vb{a}_1\ne\vb{0}$ で $\vb{a}_1,\vb{a}_2$ が線形従属のとき、グラム・シュミットの直交化をすると何が起きますか。`,[R`2 本目で正射影を引いた残りが $\vb{0}$ になり、長さ 1 にできない`,R`正規直交な 2 本が得られる`,R`1 本目が $\vb{0}$ になる`,R`平行な単位ベクトルが 2 本得られる`],R`$\vb{a}_2=k\vb{a}_1$ なら $\vb{a}_2$ は全部が $\vb{a}_1$ 方向の成分で、引くと $\vb{0}$ が残ります。長さ 0 では割れません。`);
th('sym',R`実対称行列 $A$ の異なる固有値 $\lambda\ne\mu$ に対する固有ベクトル $\vb{u},\vb{v}$ について正しいものはどれですか。`,[R`直交する`,R`平行である`,R`長さが等しい`,R`和も固有ベクトルである`],R`$\lambda\,\vb{u}\cdot\vb{v}=(A\vb{u})\cdot\vb{v}=\vb{u}\cdot(A\vb{v})=\mu\,\vb{u}\cdot\vb{v}$ です。$(\lambda-\mu)\vb{u}\cdot\vb{v}=0$ なので内積は 0 です。対称でなければ線形独立までしか言えません。`);
th('sym',R`エルミート行列の固有値について正しいものはどれですか。`,[R`すべて実数である`,R`すべて純虚数である`,R`絶対値がすべて 1 である`,R`すべて正である`],R`エルミート行列は実対称行列の複素数版で、固有値は実数です。絶対値が 1 になるのはユニタリ行列です。`);
th('sym',R`複素正方行列がユニタリ行列で対角化できることと同じ条件はどれですか。`,[R`正規行列である ($A^*A=AA^*$)`,R`正則である`,R`固有値がすべて実数である`,R`成分がすべて実数である`],R`エルミート行列、ユニタリ行列、実対称行列、直交行列はどれも正規行列です。$\M{1&1\\0&1}$ は固有値が実数ですが正規行列ではなく、対角化もできません。`);
th('sym',R`シルベスターの慣性法則が述べていることはどれですか。`,[R`二次形式を標準形に直す方法によらず、符号数は同じになる`,R`二次形式の標準形の係数は、直し方によらず同じになる`,R`対称行列の固有値はすべて正である`,R`二次形式は必ず正定値である`],R`係数そのものは変数の取り替え方で変わりますが、正の係数の個数と負の係数の個数は変わりません。`);
th('svd',R`2 次正方行列 $A$ の特異値 $\sigma_1,\sigma_2$ の積と等しいものはどれですか。`,[R`$|\det A|$`,R`$\mathrm{tr}\,A$`,R`$\det A$`,R`$\mathrm{rank}\,A$`],R`$\sigma_1^2\sigma_2^2=\det(A^{\mathsf T}A)=(\det A)^2$ です。特異値は 0 以上なので絶対値がつきます。面積の倍率を、直交する 2 方向の伸び率の積として見た式です。`);
th('svd',R`特異値分解 $A=U\Sigma V^{\mathsf T}$ の $U$ と $V$ はどんな行列ですか。`,[R`直交行列`,R`対角行列`,R`上三角行列`,R`対称行列`],R`$U$ と $V$ は長さと角度を変えない変形で、伸縮は $\Sigma$ だけが受け持ちます。`);

/* ---------- 追加: 計算 ---------- */
ca('det','余因子行列で逆行列',R`余因子行列を使って $A=\M{1&0&2\\0&1&0\\1&0&3}$ の逆行列を求めてください。`,[R`$\M{3&0&-2\\0&1&0\\-1&0&1}$`,R`$\M{3&0&-1\\0&1&0\\-2&0&1}$`,R`$\M{3&0&2\\0&1&0\\1&0&1}$`,R`$\M{-3&0&2\\0&-1&0\\1&0&-1}$`],R`$\det A=1\cdot3+2\cdot(0-1)=1$。余因子は $\tilde a_{11}=3,\ \tilde a_{13}=-1,\ \tilde a_{22}=1,\ \tilde a_{31}=-2,\ \tilde a_{33}=1$ で、ほかは 0 です。これを並べた $\M{3&0&-1\\0&1&0\\-2&0&1}$ を転置して $\det A$ で割ります。2 番目は転置を忘れたもの、3 番目は符号 $(-1)^{i+j}$ を忘れたものです。`);
ca('sys','3 次の掃き出し法で逆行列',R`$(A\mid I)$ を掃き出して $A=\M{1&1&0\\0&1&1\\0&0&1}$ の逆行列を求めてください。`,[R`$\M{1&-1&1\\0&1&-1\\0&0&1}$`,R`$\M{1&-1&0\\0&1&-1\\0&0&1}$`,R`$\M{1&0&0\\1&1&0\\0&1&1}$`,R`$\M{1&-1&-1\\0&1&-1\\0&0&1}$`],R`2 行目から 3 行目を引くと右側の 2 行目は $(0,1,-1)$。1 行目から新しい 2 行目を引くと $(1,-1,1)$ です。2 番目を $A$ に掛けると $(1,3)$ 成分が $-1$ になり、$I$ になりません。`,3);
ca('sys','基本行列を掛ける',R`$E=\M{1&0\\-3&1}$ を $A=\M{1&2\\3&4}$ に左から掛けた $EA$ を求めてください。`,[R`$\M{1&2\\0&-2}$`,R`$\M{-5&2\\-9&4}$`,R`$\M{1&2\\0&2}$`,R`$\M{-2&-4\\3&4}$`],R`$E$ は $I$ の 2 行目から 1 行目の 3 倍を引いた基本行列です。左から掛けると $A$ に同じ行基本変形が行われます。2 番目は右から掛けた $AE$ です。`);
ca('det','ブロック三角行列の行列式',R`$\D{2&1&5&7\\1&1&3&2\\0&0&3&1\\0&0&4&2}$ を求めてください。`,[R`$2$`,R`$0$`,R`$-2$`,R`$14$`],R`左下が零行列のブロックなので、対角のブロックの行列式の積です。$\D{2&1\\1&1}\cdot\D{3&1\\4&2}=1\cdot2=2$。右上のブロックは値に関係しません。`);
ca('det','置換の符号を数える',R`$1,2,3$ を $2,3,1$ に並べ替える置換の符号を求めてください。`,[R`$+1$`,R`$-1$`,R`$0$`,R`$3$`],R`$1,2,3$ から始めて、1 番目と 2 番目を入れ替えると $2,1,3$、2 番目と 3 番目を入れ替えると $2,3,1$ です。互換 2 個で作れるので符号は $+1$ です。行列式の定義では $a_{12}a_{23}a_{31}$ の項に $+$ がつきます。`);
ca('eig','3 次の固有方程式',R`$A=\M{1&2&0\\2&1&0\\0&0&3}$ の固有値を重複も含めて求めてください。`,[R`$-1,\ 3,\ 3$`,R`$1,\ 1,\ 3$`,R`$-1,\ 1,\ 3$`,R`$1,\ 2,\ 3$`],R`3 行目で展開すると $(3-\lambda)\{(1-\lambda)^2-4\}=-(\lambda-3)^2(\lambda+1)$ です。和 $5$ がトレース、積 $-9$ が行列式に一致します。2 番目は和は合いますが積が 3 です。`);
ca('eig','重解の固有空間の次元',R`$A=\M{2&1&0\\0&2&0\\0&0&3}$ の固有値 2 の (代数的重複度, 幾何的重複度) はどれですか。`,[R`$(2,\,1)$`,R`$(2,\,2)$`,R`$(1,\,1)$`,R`$(1,\,2)$`],R`固有多項式は $(2-\lambda)^2(3-\lambda)$ で代数的重複度は 2。$A-2I=\M{0&1&0\\0&0&0\\0&0&1}$ のランクは 2 なので、固有空間の次元は $3-2=1$。固有ベクトルが足りないので $A$ は対角化できません。`,3);
ca('eig','固有空間の基底を求める',R`$A=\M{2&1&1\\1&2&1\\1&1&2}$ の固有値 1 の固有空間の基底として正しいものはどれですか。`,[R`$\M{-1\\1\\0},\ \M{-1\\0\\1}$`,R`$\M{1\\1\\1}$`,R`$\M{1\\-1\\0},\ \M{-1\\1\\0}$`,R`$\M{1\\0\\0},\ \M{0\\1\\0}$`],R`$A-I$ は全成分が 1 なので、方程式は $x+y+z=0$ の 1 本で、固有空間は 2 次元です。$\M{1\\1\\1}$ は固有値 4 の固有ベクトル、3 番目は平行な 2 本、4 番目は式を満たしません。`);
ca('sym','対称行列の直交対角化',R`$A=\M{3&1\\1&3}$ について $Q^{\mathsf T}AQ=D$ となる直交行列 $Q$ と対角行列 $D$ の組はどれですか。`,[R`$Q=\dfrac{1}{\sqrt2}\M{1&1\\1&-1},\ D=\M{4&0\\0&2}$`,R`$Q=\M{1&1\\1&-1},\ D=\M{4&0\\0&2}$`,R`$Q=\dfrac{1}{\sqrt2}\M{1&1\\1&-1},\ D=\M{2&0\\0&4}$`,R`$Q=\dfrac{1}{\sqrt2}\M{1&1\\1&-1},\ D=\M{3&0\\0&3}$`],R`固有値は和 6、積 8 から 4 と 2。固有ベクトル $\M{1\\1}$ (固有値 4) と $\M{1\\-1}$ (固有値 2) は直交しているので、長さ 1 にして並べます。2 番目は列の長さが $\sqrt2$ で直交行列ではありません。3 番目は列と固有値の順序がずれています。`);
ca('rank','基底を変えた表現行列 P⁻¹AP',R`$A=\M{1&2\\0&3}$ が表す変換を、基底 $\vb{b}_1=\M{1\\1},\ \vb{b}_2=\M{0\\1}$ で表した表現行列を求めてください。`,[R`$\M{3&2\\0&1}$`,R`$\M{-1&2\\-4&5}$`,R`$\M{3&2\\3&3}$`,R`$\M{1&2\\-1&1}$`],R`$P=\M{1&0\\1&1}$ として $P^{-1}AP$ を計算します。直接確かめると $A\vb{b}_1=\M{3\\3}=3\vb{b}_1$、$A\vb{b}_2=\M{2\\3}=2\vb{b}_1+\vb{b}_2$ で、係数を列に並べた行列です。2 番目は $PAP^{-1}$、3 番目は $AP$ です。`,3);
ca('rank','小行列式でランクを判定',R`$\M{1&1&1\\1&2&3\\1&3&a}$ のランクが 2 になる $a$ を求めてください。`,[R`$5$`,R`$-5$`,R`$3$`,R`$6$`],R`左上の 2 次の行列式 $\D{1&1\\1&2}=1$ が 0 でないので、ランクはいつも 2 以上です。3 次の行列式は $a-5$ で、0 のときだけランクが 2 になります。$a=5$ では 3 行目が「2 行目の 2 倍から 1 行目を引いたもの」です。`);
ca('rank','同次方程式の解空間の基底',R`$\M{1&2&0&-1\\0&0&1&2}\vb{x}=\vb{0}$ の解空間の基底はどれですか。`,[R`$\M{-2\\1\\0\\0},\ \M{1\\0\\-2\\1}$`,R`$\M{-2\\1\\0\\0}$`,R`$\M{1\\2\\0\\-1},\ \M{0\\0\\1\\2}$`,R`$\M{-2\\1\\0\\0},\ \M{1\\0\\2\\1}$`],R`ピボットのない $x_2=s$、$x_4=t$ を自由変数にとると $x_3=-2t$、$x_1=-2s+t$。解空間の次元は $4-2=2$ で、1 本では足りません。3 番目は行空間の基底、4 番目は 2 本目の式を満たしません。`,3);
ca('orth','最小二乗法 (切片のある直線)',R`3 点 $(0,1),(1,3),(2,4)$ に直線 $y=a+bx$ を最小二乗法で当てはめてください。`,[R`$y=\dfrac76+\dfrac32x$`,R`$y=1+\dfrac32x$`,R`$y=\dfrac{11}5x$`,R`$y=\dfrac43+x$`],R`$A=\M{1&0\\1&1\\1&2}$、$\vb{b}=\M{1\\3\\4}$。$A^{\mathsf T}A=\M{3&3\\3&5}$、$A^{\mathsf T}\vb{b}=\M{8\\11}$。$3a+3b=8$、$3a+5b=11$ から $b=\dfrac32$、$a=\dfrac76$。誤差の 2 乗の和は $\dfrac16$ で、2 番目の $\dfrac14$ より小さくなります。3 番目は切片なしで解いたものです。`);
ca('orth','QR 分解',R`$A=\M{3&1\\4&0}$ を $A=QR$ ($Q$ は直交行列、$R$ は対角成分が正の上三角行列) と分解したときの $R$ を求めてください。`,[R`$\M{5&3/5\\0&4/5}$`,R`$\M{5&3\\0&4}$`,R`$\M{5&3/5\\0&1}$`,R`$\M{1&3/5\\0&4/5}$`],R`グラム・シュミットで $\vb{u}_1=\M{3/5\\4/5}$、$\vb{u}_2=\M{4/5\\-3/5}$。$R=Q^{\mathsf T}A$ で、$r_{11}=\|\vb{a}_1\|=5$、$r_{12}=\vb{u}_1\cdot\vb{a}_2=\dfrac35$、$r_{22}=\vb{u}_2\cdot\vb{a}_2=\dfrac45$ です。`);
ca('svd','一般の 2 次行列の特異値',R`$A=\M{3&0\\4&5}$ の特異値を求めてください。`,[R`$3\sqrt5,\ \sqrt5$`,R`$5,\ 3$`,R`$45,\ 5$`,R`$15,\ 1$`],R`$A^{\mathsf T}A=\M{25&20\\20&25}$ の固有値は $45$ と $5$。平方根を取って $3\sqrt5$ と $\sqrt5$。積が $|\det A|=15$ になることで確かめられます。2 番目は $A$ の固有値、3 番目は平方根を取り忘れたものです。`);
ca('svd','ランク 1 の行列の特異値分解',R`$A=\M{1&1\\1&1}=\sigma_1\vb{u}_1\vb{v}_1^{\mathsf T}$ と書くときの組はどれですか。`,[R`$\sigma_1=2,\ \vb{u}_1=\vb{v}_1=\dfrac1{\sqrt2}\M{1\\1}$`,R`$\sigma_1=4,\ \vb{u}_1=\vb{v}_1=\dfrac1{\sqrt2}\M{1\\1}$`,R`$\sigma_1=\sqrt2,\ \vb{u}_1=\vb{v}_1=\M{1\\1}$`,R`$\sigma_1=2,\ \vb{u}_1=\dfrac1{\sqrt2}\M{1\\-1},\ \vb{v}_1=\dfrac1{\sqrt2}\M{1\\1}$`],R`$A^{\mathsf T}A=\M{2&2\\2&2}$ の固有値は 4 と 0 なので $\sigma_1=2$、$\vb{v}_1=\dfrac1{\sqrt2}\M{1\\1}$。$\vb{u}_1=A\vb{v}_1/\sigma_1=\dfrac1{\sqrt2}\M{1\\1}$。$2\cdot\dfrac12\M{1&1\\1&1}=A$ で確かめられます。3 番目は $\vb{u}_1,\vb{v}_1$ の長さが 1 になっていません。`);
ca('sym','二次形式の標準形',R`二次形式 $5x^2+4xy+2y^2$ を直交行列による変数の取り替えで $\alpha X^2+\beta Y^2$ ($\alpha\ge\beta$) の形にしたものはどれですか。`,[R`$6X^2+Y^2$`,R`$5X^2+2Y^2$`,R`$6X^2-Y^2$`,R`$4X^2+3Y^2$`],R`行列は $\M{5&2\\2&2}$。固有値は和 7、積 6 から 6 と 1 で、これが係数になります。どちらも正なので正定値です。2 番目は対角成分を並べただけで、$xy$ の項が消えていません。`);
ca('sym','符号数を求める',R`二次形式 $x^2+4xy+y^2$ の符号数 (正の係数の個数, 負の係数の個数) を求めてください。`,[R`$(1,\,1)$`,R`$(2,\,0)$`,R`$(0,\,2)$`,R`$(1,\,0)$`],R`行列は $\M{1&2\\2&1}$ で、固有値は和 2、積 $-3$ から $3$ と $-1$ です。正が 1 個、負が 1 個で、不定符号です。$x^2$ と $y^2$ の係数が正でも正定値とは限りません。`);
ca('sym','エルミート行列の判定',R`次のうちエルミート行列はどれですか。`,[R`$\M{1&i\\-i&2}$`,R`$\M{1&i\\i&2}$`,R`$\M{i&0\\0&i}$`,R`$\M{0&1\\-1&0}$`],R`転置して共役を取ると元に戻るものを選びます。対角成分は実数で、対角の外は互いに共役でなければなりません。2 番目は対角の外が共役になっていません。3 番目は対角成分が実数ではありません。4 番目は転置すると符号が変わります。`);
ca('eig','ケーリー・ハミルトンの定理でべき乗',R`$A=\M{1&1\\0&2}$ のとき、$A^4$ を $aA+bI$ の形で表してください。`,[R`$15A-14I$`,R`$16A-15I$`,R`$15A+14I$`,R`$8A-7I$`],R`固有多項式は $x^2-3x+2$ なので $A^2=3A-2I$ です。$x^4$ をこれで割った余りを $ax+b$ とおき、$x=1,2$ を代入すると $a+b=1$、$2a+b=16$。よって $a=15$、$b=-14$。実際に $A^4=\M{1&15\\0&16}$ です。`);
ca('diag','漸化式を対角化で解く',R`$a_0=0,\ a_1=1,\ a_{n+2}=a_{n+1}+2a_n$ の一般項を求めてください。`,[R`$a_n=\dfrac{2^n-(-1)^n}{3}$`,R`$a_n=\dfrac{2^n+(-1)^n}{3}$`,R`$a_n=2^n-1$`,R`$a_n=\dfrac{2^n-(-1)^n}{2}$`],R`$\M{a_{n+1}\\a_n}=\M{1&2\\1&0}\M{a_n\\a_{n-1}}$ で、固有値は 2 と $-1$。$a_n=c_12^n+c_2(-1)^n$ に $a_0=0$、$a_1=1$ を入れて $c_1=\dfrac13$、$c_2=-\dfrac13$。$a_2=1$、$a_3=3$ で確かめられます。2 番目は $a_0=\dfrac23$、3 番目は $a_2=3$、4 番目は $a_1=\dfrac32$ になります。`);
ca('diag','対称でない行列の対角化で Aⁿ',R`$A=\M{4&-2\\1&1}$ のとき、$A^n$ の $(1,1)$ 成分を求めてください。`,[R`$2\cdot3^n-2^n$`,R`$3^n-2^n$`,R`$3^n+2^n$`,R`$2\cdot3^n+2^n$`],R`固有値は 2 (固有ベクトル $\M{1\\1}$) と 3 (固有ベクトル $\M{2\\1}$)。$P=\M{1&2\\1&1}$、$P^{-1}=\M{-1&2\\1&-1}$。$PD^nP^{-1}$ の $(1,1)$ 成分は $-2^n+2\cdot3^n$。$n=1$ で 4、$n=2$ で 14 となり、$A$ と $A^2$ の成分に一致します。`,3);
ca('det','ヴァンデルモンドの行列式',R`$\D{1&1&1\\a&b&c\\a^2&b^2&c^2}$ を因数分解した形はどれですか。`,[R`$(b-a)(c-a)(c-b)$`,R`$(a-b)(a-c)(b-c)$`,R`$abc$`,R`$(a+b+c)(b-a)(c-b)$`],R`$a=b$ なら 2 つの列が一致して 0 になるので $(b-a)$ を因数にもちます。同じように $(c-a),(c-b)$ も因数で、全体は 3 次式なので定数倍を除いて決まります。対角成分の積 $bc^2$ の係数を比べると定数は 1 です。2 番目は符号が逆です。`);
ca('det','多重線形性と交代性を使う',R`3 次正方行列 $(\vb{a}\ \vb{b}\ \vb{c})$ の行列式が 5 のとき、$\det(\vb{a}+2\vb{b}\ \ \vb{b}\ \ 3\vb{c})$ を求めてください。`,[R`$15$`,R`$5$`,R`$30$`,R`$45$`],R`1 列目から 2 列目の 2 倍を引いても値は変わらないので $\det(\vb{a}\ \vb{b}\ 3\vb{c})$ と同じです。3 列目の 3 倍は値を 3 倍にします。$5\times3=15$。`);
ca('det','行列式で体積を求める',R`$\M{1\\1\\1},\ \M{0\\2\\1},\ \M{0\\0\\3}$ を 3 辺とする平行六面体の体積を求めてください。`,[R`$6$`,R`$1$`,R`$3$`,R`$2$`],R`3 本を列に並べた行列は下三角で、行列式は $1\cdot2\cdot3=6$。体積はその絶対値です。2 番目は同じ 3 辺の四面体の体積です。`);
ca('sys','文字を含む方程式の解の判定',R`$\begin{cases}x+2y=3\\2x+ay=b\end{cases}$ が無数の解をもつ条件はどれですか。`,[R`$a=4$ かつ $b=6$`,R`$a=4$ かつ $b\ne6$`,R`$a\ne4$`,R`$a=6$ かつ $b=4$`],R`2 式目から 1 式目の 2 倍を引くと $(a-4)y=b-6$ です。$a\ne4$ なら解はただ 1 つ。$a=4$ のとき $b=6$ なら無数、$b\ne6$ なら解なしです。`);
ca('sys','LU 分解',R`$A=\M{2&1\\4&5}=LU$ ($L$ は対角成分が 1 の下三角行列、$U$ は上三角行列) と分解してください。`,[R`$L=\M{1&0\\2&1},\ U=\M{2&1\\0&3}$`,R`$L=\M{1&0\\-2&1},\ U=\M{2&1\\0&3}$`,R`$L=\M{1&0\\2&1},\ U=\M{2&1\\0&5}$`,R`$L=\M{2&0\\4&1},\ U=\M{1&1\\0&3}$`],R`2 行目から 1 行目の 2 倍を引くと $U=\M{2&1\\0&3}$。引いた倍率 2 を $L$ の $(2,1)$ 成分に入れます。2 番目は消去に使った基本行列をそのまま入れたもので、積は $\M{2&1\\-4&1}$ になります。`);
ca('det','3 次のクラメルの公式',R`クラメルの公式で $\begin{cases}x+y+z=6\\x+2y+3z=14\\x+4y+9z=36\end{cases}$ の $y$ を求めてください。`,[R`$2$`,R`$1$`,R`$3$`,R`$4$`],R`$\det A=\D{1&1&1\\1&2&3\\1&4&9}=2$。2 列目を右辺に替えた $\D{1&6&1\\1&14&3\\1&36&9}=4$。$y=\dfrac42=2$。解は $(1,2,3)$ です。4 番目は分子の値です。`);
ca('comb','3 次の行列式で独立性を判定',R`$\M{1\\1\\0},\ \M{0\\1\\1},\ \M{1\\0\\a}$ が線形従属になる $a$ を求めてください。`,[R`$-1$`,R`$1$`,R`$0$`,R`$2$`],R`3 本を列に並べた行列式は $a+1$ で、0 になるのは $a=-1$ のときです。このとき $\M{1\\0\\-1}$ は 1 本目から 2 本目を引いたものです。`);
ca('dot','外積で平行四辺形の面積',R`$\M{1\\0\\2}$ と $\M{0\\1\\3}$ を 2 辺とする平行四辺形の面積を求めてください。`,[R`$\sqrt{14}$`,R`$6$`,R`$\sqrt{50}$`,R`$\dfrac{\sqrt{14}}2$`],R`外積は $\M{-2\\-3\\1}$ で、長さは $\sqrt{4+9+1}=\sqrt{14}$。2 番目は内積、3 番目は長さの積、4 番目は三角形の面積です。`);
ca('orth','外積で直交補空間を求める',R`$\M{1\\2\\0}$ と $\M{0\\1\\1}$ が張る部分空間 $W$ の直交補空間 $W^\perp$ を張るベクトルはどれですか。`,[R`$\M{2\\-1\\1}$`,R`$\M{2\\1\\1}$`,R`$\M{1\\3\\1}$`,R`$\M{-2\\-1\\1}$`],R`$\dim W^\perp=3-2=1$ です。両方に直交するベクトルは外積で求まり $\M{2\\-1\\1}$。両方との内積が 0 になることで確かめます。3 番目は 2 本の和で、$W$ の中にあります。`);
ca('orth','平面への正射影',R`$\vb{b}=\M{1\\2\\3}$ の平面 $x+y+z=0$ への正射影を求めてください。`,[R`$\M{-1\\0\\1}$`,R`$\M{2\\2\\2}$`,R`$\M{0\\1\\2}$`,R`$\M{1/3\\2/3\\1}$`],R`法線 $\vb{n}=\M{1\\1\\1}$ の方向の成分 $\dfrac{\vb{b}\cdot\vb{n}}{\vb{n}\cdot\vb{n}}\vb{n}=2\vb{n}$ を引いて $\M{-1\\0\\1}$。成分の和が 0 で平面上にあることを確かめます。2 番目は引いた法線成分そのもの、3 番目は平面上にありません。`);
ca('orth','正規直交基底の座標を内積で求める',R`正規直交基底 $\vb{u}_1=\dfrac1{\sqrt2}\M{1\\1},\ \vb{u}_2=\dfrac1{\sqrt2}\M{1\\-1}$ での $\M{3\\1}$ の座標を求めてください。`,[R`$(2\sqrt2,\ \sqrt2)$`,R`$(2,\ 1)$`,R`$(4,\ 2)$`,R`$(\sqrt2,\ 2\sqrt2)$`],R`連立方程式を解かずに、内積 $\vb{p}\cdot\vb{u}_i$ で座標が求まります。$\dfrac{4}{\sqrt2}=2\sqrt2$、$\dfrac{2}{\sqrt2}=\sqrt2$。2 番目は長さを 1 にする前の基底での座標です。`);
ca('space','多項式の空間での座標',R`2 次以下の多項式の空間の基底 $1,\ 1+x,\ (1+x)^2$ での $3+2x+x^2$ の座標を求めてください。`,[R`$(2,\ 0,\ 1)$`,R`$(3,\ 2,\ 1)$`,R`$(2,\ 2,\ 1)$`,R`$(1,\ 0,\ 2)$`],R`$a+b(1+x)+c(1+x)^2$ の $x^2$ の係数から $c=1$、$x$ の係数から $b+2c=2$ で $b=0$、定数項から $a+b+c=3$ で $a=2$。2 番目は基底 $1,x,x^2$ での座標です。`);
ca('rank','微分の表現行列',R`2 次以下の多項式の空間で、微分 $D(p)=p'$ を基底 $1,\ x,\ x^2$ で表した表現行列を求めてください。`,[R`$\M{0&1&0\\0&0&2\\0&0&0}$`,R`$\M{0&0&0\\1&0&0\\0&2&0}$`,R`$\M{0&1&0\\0&0&1\\0&0&0}$`,R`$\M{1&0&0\\0&2&0\\0&0&0}$`],R`$D(1)=0$、$D(x)=1$、$D(x^2)=2x$ の座標を列に並べます。2 番目は行に並べたものです。この行列の固有値は 0 だけで、対角化できません。`);
ca('orth','3 次元のグラム・シュミット',R`$\vb{a}_1=\M{1\\1\\0},\ \vb{a}_2=\M{1\\0\\1}$ をこの順に直交化したときの $\vb{u}_2$ を求めてください。`,[R`$\dfrac1{\sqrt6}\M{1\\-1\\2}$`,R`$\dfrac1{\sqrt2}\M{1\\0\\1}$`,R`$\dfrac1{\sqrt2}\M{1\\-1\\0}$`,R`$\dfrac12\M{1\\-1\\2}$`],R`$\vb{a}_2-\dfrac{\vb{a}_2\cdot\vb{a}_1}{\vb{a}_1\cdot\vb{a}_1}\vb{a}_1=\M{1\\0\\1}-\dfrac12\M{1\\1\\0}=\M{1/2\\-1/2\\1}$。長さ $\dfrac{\sqrt6}2$ で割ります。2 番目は正射影を引いていません。3 番目は $\vb{a}_1$ と直交しますが、$\vb{a}_1,\vb{a}_2$ の張る平面の外にあります。4 番目は長さが 1 になっていません。`);
